// Package views defines the View interface for ecsx TUI views.
package views

import tea "charm.land/bubbletea/v2"

// View is the interface that all ecsx views implement.
// Each view is a self-contained bubbletea sub-model that manages
// its own state, keybindings, and rendering.
type View interface {
	// Init returns the initial command for this view.
	Init() tea.Cmd

	// Update handles messages and returns the updated view and any commands.
	Update(msg tea.Msg) (View, tea.Cmd)

	// View renders the view content.
	View() string

	// Focused returns whether this view is currently focused.
	Focused() bool

	// SetFocused sets the focus state of this view.
	SetFocused(focused bool)

	// SetSize updates the view dimensions.
	SetSize(width, height int)

	// HelpText returns the contextual help string for the bottom bar.
	HelpText() string
}

package clusters

import (
	"fmt"
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/bubbles/v2/list"
	"charm.land/bubbles/v2/viewport"
	"charm.land/lipgloss/v2"

	ecsaws "github.com/ron/ecsx/internal/aws"
	"github.com/ron/ecsx/internal/ui/messages"
)

// View is the clusters list view with a detail pane.
type View struct {
	client ecsaws.ECSClient
	list   list.Model
	detail viewport.Model

	focused bool
	width   int
	height  int
}

// New creates a new clusters view.
func New(client ecsaws.ECSClient) *View {
	l := list.New(nil, list.NewDefaultDelegate(), 0, 0)
	l.Title = "Clusters"
	l.SetShowStatusBar(false)
	l.SetShowHelp(false)
	l.SetFilteringEnabled(true)

	return &View{
		client:  client,
		list:    l,
		detail:  viewport.New(),
		focused: true,
	}
}

func (v *View) Init() tea.Cmd {
	return nil // Loading is triggered by the root model
}

func (v *View) Update(msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case messages.ClustersLoaded:
		items := make([]list.Item, len(msg.Clusters))
		for i, c := range msg.Clusters {
			items[i] = clusterItem{c}
		}
		cmd := v.list.SetItems(items)
		v.list.Select(0)
		v.updateDetail()
		return cmd

	case tea.KeyPressMsg:
		if v.list.FilterState() == list.Filtering {
			var cmd tea.Cmd
			v.list, cmd = v.list.Update(msg)
			return cmd
		}

		switch msg.String() {
		case "enter":
			return v.handleEnter()
		case "x":
			return v.handleSSM()
		}
	}

	// Delegate to list for navigation
	prevName := ""
	if sel := v.list.SelectedItem(); sel != nil {
		prevName = sel.FilterValue()
	}
	var cmd tea.Cmd
	v.list, cmd = v.list.Update(msg)
	curName := ""
	if sel := v.list.SelectedItem(); sel != nil {
		curName = sel.FilterValue()
	}
	if curName != prevName {
		v.updateDetail()
	}
	return cmd
}

func (v *View) View() string {
	return v.list.View()
}

func (v *View) DetailView() string {
	return v.detail.View()
}

func (v *View) Focused() bool        { return v.focused }
func (v *View) SetFocused(f bool)     { v.focused = f }

func (v *View) SetSize(width, height int) {
	v.width = width
	v.height = height
	listW := width * 2 / 5
	detailW := width - listW
	v.list.SetSize(listW-2, height)
	v.detail.SetWidth(detailW - 2)
	v.detail.SetHeight(height)
}

func (v *View) HelpText() string {
	parts := []string{"↑↓ navigate", "/ filter", "enter select", "x ssm", "r refresh", "? help", "q quit"}
	return "  " + strings.Join(parts, " • ")
}

// SetItems updates the list items, preserving selection if refreshing.
func (v *View) SetItems(clusters []ecsaws.Cluster, preserveSelection bool) tea.Cmd {
	prevSel := ""
	if sel := v.list.SelectedItem(); sel != nil {
		prevSel = sel.FilterValue()
	}
	items := make([]list.Item, len(clusters))
	for i, c := range clusters {
		items[i] = clusterItem{c}
	}
	cmd := v.list.SetItems(items)
	if preserveSelection {
		for i, item := range items {
			if item.FilterValue() == prevSel {
				v.list.Select(i)
				break
			}
		}
	} else {
		v.list.ResetFilter()
		v.list.Select(0)
	}
	v.updateDetail()
	return cmd
}

// SelectedCluster returns the currently selected cluster, if any.
func (v *View) SelectedCluster() *ecsaws.Cluster {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	c := sel.(clusterItem).cluster
	return &c
}

// FilterState returns the current filter state of the list.
func (v *View) FilterState() list.FilterState {
	return v.list.FilterState()
}

func (v *View) handleEnter() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	c := sel.(clusterItem).cluster
	return func() tea.Msg {
		return clusterSelectedMsg{cluster: c}
	}
}

func (v *View) handleSSM() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	c := sel.(clusterItem).cluster
	return func() tea.Msg {
		return clusterSSMMsg{clusterName: c.Name}
	}
}

func (v *View) updateDetail() {
	sel := v.list.SelectedItem()
	if sel == nil {
		v.detail.SetContent("  No items")
		return
	}
	c := sel.(clusterItem).cluster
	v.renderClusterDetail(c)
}

func (v *View) renderClusterDetail(c ecsaws.Cluster) {
	region := v.client.Region()
	link := fmt.Sprintf("https://%s.console.aws.amazon.com/ecs/home?region=%s#/clusters/%s", region, region, c.Name)

	titleStyle := lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("69")).PaddingLeft(1)
	labelStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("243"))

	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", titleStyle.Render(c.Name))
	kv(&b, labelStyle, "Status", c.Status)
	kv(&b, labelStyle, "Container Instances", fmt.Sprintf("%d", c.ContainerInstances))
	kv(&b, labelStyle, "Active Services", fmt.Sprintf("%d", c.ActiveServices))
	kv(&b, labelStyle, "Running Tasks", fmt.Sprintf("%d", c.RunningTasks))
	kv(&b, labelStyle, "Pending Tasks", fmt.Sprintf("%d", c.PendingTasks))

	maxW := v.width - v.width*2/5 - 8
	if maxW > 0 && len(link) > maxW {
		link = link[:maxW] + "…"
	}
	fmt.Fprintf(&b, "\n  Console:\n  %s\n", link)
	v.detail.SetContent(b.String())
}

func kv(b *strings.Builder, labelStyle lipgloss.Style, key, val string) {
	label := labelStyle.Render(fmt.Sprintf("  %-22s", key))
	fmt.Fprintf(b, "%s %s\n", label, val)
}

// Internal messages emitted by this view for the root model to handle.
type clusterSelectedMsg struct{ cluster ecsaws.Cluster }
type clusterSSMMsg struct{ clusterName string }

// ClusterSelectedMsg is the exported accessor for the root model.
func IsClusterSelected(msg tea.Msg) (ecsaws.Cluster, bool) {
	if m, ok := msg.(clusterSelectedMsg); ok {
		return m.cluster, true
	}
	return ecsaws.Cluster{}, false
}

// IsClusterSSM checks if the message is a request to start SSM for a cluster.
func IsClusterSSM(msg tea.Msg) (string, bool) {
	if m, ok := msg.(clusterSSMMsg); ok {
		return m.clusterName, true
	}
	return "", false
}

// clusterItem implements list.Item for clusters.
type clusterItem struct{ cluster ecsaws.Cluster }

func (i clusterItem) Title() string { return i.cluster.Name }
func (i clusterItem) Description() string {
	return fmt.Sprintf("services=%d running=%d pending=%d",
		i.cluster.ActiveServices, i.cluster.RunningTasks, i.cluster.PendingTasks)
}
func (i clusterItem) FilterValue() string { return i.cluster.Name }

package services

import (
	"context"
	"fmt"
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/bubbles/v2/list"
	"charm.land/bubbles/v2/textinput"
	"charm.land/bubbles/v2/viewport"
	"charm.land/lipgloss/v2"

	ecsaws "github.com/ron/ecsx/internal/aws"
	"github.com/ron/ecsx/internal/ui/messages"
)

// View is the services list view with a detail pane.
type View struct {
	client      ecsaws.ECSClient
	list        list.Model
	detail      viewport.Model
	clusterName string

	// Metrics cache
	metricsMap map[string]*ecsaws.ServiceMetrics

	// Env vars state
	showEnvVars bool
	envVars     []ecsaws.ContainerDefinition

	// Scale state
	scaling    bool
	scaleInput textinput.Model
	scaleSvc   string
	scaleCount int32

	// Confirm state
	confirming    bool
	confirmAction string // "scale", "deploy"

	focused bool
	width   int
	height  int
}

// New creates a new services view.
func New(client ecsaws.ECSClient) *View {
	l := list.New(nil, list.NewDefaultDelegate(), 0, 0)
	l.Title = "Services"
	l.SetShowStatusBar(false)
	l.SetShowHelp(false)
	l.SetFilteringEnabled(true)

	return &View{
		client:     client,
		list:       l,
		detail:     viewport.New(),
		metricsMap: make(map[string]*ecsaws.ServiceMetrics),
		focused:    true,
	}
}

func (v *View) Init() tea.Cmd {
	return nil
}

func (v *View) Update(msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case messages.ServiceNamesLoaded:
		return v.handleServiceNamesLoaded(msg, false)

	case messages.ServiceDetailLoaded:
		return v.handleServiceDetailLoaded(msg)

	case messages.ServicesLoaded:
		return v.handleServicesLoaded(msg)

	case messages.MetricsLoaded:
		v.metricsMap[msg.Service] = msg.Metrics
		v.updateDetail()
		return nil

	case messages.EnvVarsLoaded:
		v.showEnvVars = true
		v.envVars = msg.Containers
		v.updateDetail()
		return nil

	case messages.ServiceScaled:
		return v.loadServiceNames()

	case messages.ServiceRedeployed:
		return v.loadServiceNames()

	case tea.KeyPressMsg:
		if v.scaling {
			return v.handleScalingKey(msg)
		}
		if v.confirming {
			return v.handleConfirmKey(msg)
		}
		if v.list.FilterState() == list.Filtering {
			var cmd tea.Cmd
			v.list, cmd = v.list.Update(msg)
			return cmd
		}

		switch msg.String() {
		case "enter":
			return v.handleEnter()
		case "esc":
			return v.handleEsc()
		case "e":
			return v.handleEnvVars()
		case "s":
			return v.handleScale()
		case "x":
			return v.handleForceNewDeployment()
		case "l":
			return v.handleLogs()
		case "y":
			if v.showEnvVars {
				return v.handleYank()
			}
		}
	}

	// Delegate to list for navigation
	prevName := ""
	if sel := v.list.SelectedItem(); sel != nil {
		prevName = sel.FilterValue()
	}
	var cmd tea.Cmd
	v.list, cmd = v.list.Update(msg)
	curName := ""
	if sel := v.list.SelectedItem(); sel != nil {
		curName = sel.FilterValue()
	}
	if curName != prevName {
		v.updateDetail()
		if curName != "" {
			si := v.list.SelectedItem().(serviceItem)
			if si.service == nil {
				return tea.Batch(cmd, v.loadServiceDetail(curName))
			}
			if _, ok := v.metricsMap[si.name]; !ok {
				return tea.Batch(cmd, v.loadMetrics(curName))
			}
		}
	}
	return cmd
}

func (v *View) View() string {
	return v.list.View()
}

func (v *View) DetailView() string {
	return v.detail.View()
}

func (v *View) Focused() bool        { return v.focused }
func (v *View) SetFocused(f bool)     { v.focused = f }

func (v *View) SetSize(width, height int) {
	v.width = width
	v.height = height
	listW := width * 2 / 5
	detailW := width - listW
	v.list.SetSize(listW-2, height)
	v.detail.SetWidth(detailW - 2)
	v.detail.SetHeight(height)
}

func (v *View) SetCluster(name string) {
	v.clusterName = name
	v.list.Title = fmt.Sprintf("Services (%s)", name)
	v.metricsMap = make(map[string]*ecsaws.ServiceMetrics)
}

func (v *View) HelpText() string {
	parts := []string{"↑↓ navigate", "/ filter", "enter select", "esc back", "e env vars", "l logs", "s scale", "x deploy"}
	if v.showEnvVars {
		parts = append(parts, "y yank")
	}
	parts = append(parts, "r refresh", "? help", "q quit")
	return "  " + strings.Join(parts, " • ")
}

// IsScaling returns whether the view is in scaling mode.
func (v *View) IsScaling() bool { return v.scaling }

// IsConfirming returns whether the view is in confirm mode.
func (v *View) IsConfirming() bool { return v.confirming }

// FilterState returns the current filter state of the list.
func (v *View) FilterState() list.FilterState {
	return v.list.FilterState()
}

// SetItems updates the list items, preserving selection if refreshing.
func (v *View) SetItems(names []string, preserveSelection bool) tea.Cmd {
	prevSel := ""
	if sel := v.list.SelectedItem(); sel != nil {
		prevSel = sel.FilterValue()
	}
	items := make([]list.Item, len(names))
	for i, name := range names {
		items[i] = serviceItem{name: name}
	}
	cmd := v.list.SetItems(items)
	if preserveSelection {
		for i, item := range items {
			if item.FilterValue() == prevSel {
				v.list.Select(i)
				break
			}
		}
	} else {
		v.list.ResetFilter()
		v.metricsMap = make(map[string]*ecsaws.ServiceMetrics)
		v.list.Select(0)
	}
	v.updateDetail()
	if len(names) > 0 {
		sel := v.list.SelectedItem()
		if sel != nil {
			return tea.Batch(cmd, v.loadServiceDetail(sel.FilterValue()))
		}
	}
	return cmd
}

// SelectedServiceName returns the name of the currently selected service.
func (v *View) SelectedServiceName() string {
	sel := v.list.SelectedItem()
	if sel == nil {
		return ""
	}
	return sel.(serviceItem).name
}

// --- Internal handlers ---

func (v *View) handleServiceNamesLoaded(msg messages.ServiceNamesLoaded, preserveSelection bool) tea.Cmd {
	return v.SetItems(msg.Names, preserveSelection)
}

func (v *View) handleServiceDetailLoaded(msg messages.ServiceDetailLoaded) tea.Cmd {
	items := v.list.Items()
	for i, item := range items {
		if si, ok := item.(serviceItem); ok && si.name == msg.Name {
			items[i] = serviceItem{name: msg.Name, service: msg.Service}
			break
		}
	}
	cmd := v.list.SetItems(items)
	if sel := v.list.SelectedItem(); sel != nil {
		if si, ok := sel.(serviceItem); ok && si.name == msg.Name {
			v.updateDetail()
			if _, ok := v.metricsMap[msg.Name]; !ok {
				return tea.Batch(cmd, v.loadMetrics(msg.Name))
			}
		}
	}
	return cmd
}

func (v *View) handleServicesLoaded(msg messages.ServicesLoaded) tea.Cmd {
	v.metricsMap = make(map[string]*ecsaws.ServiceMetrics)
	items := make([]list.Item, len(msg.Services))
	for i, s := range msg.Services {
		s := s
		items[i] = serviceItem{name: s.Name, service: &s}
	}
	cmd := v.list.SetItems(items)
	v.list.ResetFilter()
	v.list.Select(0)
	v.updateDetail()
	if len(msg.Services) > 0 {
		return tea.Batch(cmd, v.loadMetrics(msg.Services[0].Name))
	}
	return cmd
}

func (v *View) handleEnter() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	s := sel.(serviceItem)
	if s.service == nil {
		return nil
	}
	return func() tea.Msg {
		return ServiceSelectedMsg{ServiceName: s.name}
	}
}

func (v *View) handleEsc() tea.Cmd {
	if v.showEnvVars {
		v.showEnvVars = false
		v.envVars = nil
		v.updateDetail()
		return nil
	}
	return func() tea.Msg {
		return GoBackMsg{}
	}
}

func (v *View) handleEnvVars() tea.Cmd {
	if v.showEnvVars {
		v.showEnvVars = false
		v.envVars = nil
		v.updateDetail()
		return nil
	}
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	s := sel.(serviceItem)
	if s.service == nil {
		return nil
	}
	taskDef := s.service.TaskDefinition
	if taskDef == "" {
		return nil
	}
	client := v.client
	return func() tea.Msg {
		containers, err := client.DescribeTaskDefinition(context.Background(), taskDef)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.EnvVarsLoaded{Containers: containers}
	}
}

func (v *View) handleScale() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	svc := sel.(serviceItem).service
	if svc == nil {
		return nil
	}
	v.scaling = true
	v.scaleSvc = svc.Name
	ti := textinput.New()
	ti.Placeholder = "desired count"
	ti.SetValue(fmt.Sprintf("%d", svc.DesiredCount))
	ti.CharLimit = 5
	ti.SetWidth(20)
	v.scaleInput = ti
	cmd := v.scaleInput.Focus()
	v.updateDetail()
	return cmd
}

func (v *View) handleScalingKey(msg tea.KeyPressMsg) tea.Cmd {
	switch msg.String() {
	case "enter":
		return v.confirmScale()
	case "esc":
		v.scaling = false
		v.updateDetail()
		return nil
	}
	var cmd tea.Cmd
	v.scaleInput, cmd = v.scaleInput.Update(msg)
	v.updateDetail()
	return cmd
}

func (v *View) confirmScale() tea.Cmd {
	val := v.scaleInput.Value()
	var count int
	if _, err := fmt.Sscanf(val, "%d", &count); err != nil || count < 0 {
		v.scaling = false
		return func() tea.Msg {
			return messages.Err{Err: fmt.Errorf("invalid count: %s", val)}
		}
	}
	v.scaling = false
	v.confirming = true
	v.confirmAction = "scale"
	v.scaleCount = int32(count)
	v.updateDetail()
	return nil
}

func (v *View) handleConfirmKey(msg tea.KeyPressMsg) tea.Cmd {
	switch msg.String() {
	case "enter":
		switch v.confirmAction {
		case "deploy":
			return v.executeForceNewDeployment()
		default:
			return v.executeScale()
		}
	case "esc":
		v.confirming = false
		v.confirmAction = ""
		v.updateDetail()
		return nil
	}
	return nil
}

func (v *View) executeScale() tea.Cmd {
	v.confirming = false
	cluster := v.clusterName
	svc := v.scaleSvc
	count := v.scaleCount
	client := v.client
	return func() tea.Msg {
		err := client.UpdateServiceDesiredCount(context.Background(), cluster, svc, count)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.ServiceScaled{}
	}
}

func (v *View) handleForceNewDeployment() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	svc := sel.(serviceItem).service
	if svc == nil {
		return nil
	}
	v.confirming = true
	v.confirmAction = "deploy"
	v.scaleSvc = svc.Name
	v.updateDetail()
	return nil
}

func (v *View) executeForceNewDeployment() tea.Cmd {
	v.confirming = false
	v.confirmAction = ""
	cluster := v.clusterName
	svc := v.scaleSvc
	client := v.client
	return func() tea.Msg {
		err := client.ForceNewDeployment(context.Background(), cluster, svc)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.ServiceRedeployed{}
	}
}

func (v *View) handleLogs() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	s := sel.(serviceItem)
	if s.service == nil {
		return nil
	}
	return func() tea.Msg {
		return LogsRequestedMsg{ServiceName: s.name}
	}
}

func (v *View) handleYank() tea.Cmd {
	if v.envVars == nil {
		return nil
	}
	return func() tea.Msg {
		return YankEnvVarsMsg{Containers: v.envVars}
	}
}

func (v *View) loadServiceNames() tea.Cmd {
	client := v.client
	cluster := v.clusterName
	return func() tea.Msg {
		names, err := client.ListServiceNames(context.Background(), cluster)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.ServiceNamesLoaded{Names: names}
	}
}

func (v *View) loadServiceDetail(name string) tea.Cmd {
	client := v.client
	cluster := v.clusterName
	return func() tea.Msg {
		svc, err := client.DescribeService(context.Background(), cluster, name)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.ServiceDetailLoaded{Name: name, Service: svc}
	}
}

func (v *View) loadMetrics(name string) tea.Cmd {
	client := v.client
	cluster := v.clusterName
	return func() tea.Msg {
		metrics, err := client.GetServiceMetrics(context.Background(), cluster, name)
		if err != nil {
			return messages.MetricsLoaded{Service: name, Metrics: &ecsaws.ServiceMetrics{}}
		}
		return messages.MetricsLoaded{Service: name, Metrics: metrics}
	}
}

func (v *View) updateDetail() {
	titleStyle := lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("69")).PaddingLeft(1)
	labelStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("243"))
	helpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	warnStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true).PaddingLeft(1)

	if v.confirming {
		switch v.confirmAction {
		case "deploy":
			var b strings.Builder
			fmt.Fprintf(&b, "%s\n\n", titleStyle.Render("Force New Deployment"))
			fmt.Fprintf(&b, "  Service: %s\n\n", v.scaleSvc)
			fmt.Fprintf(&b, "  %s\n\n", warnStyle.Render("⚠ This will trigger a rolling restart of all tasks."))
			fmt.Fprintf(&b, "  %s\n", helpStyle.Render("enter confirm • esc cancel"))
			v.detail.SetContent(b.String())
			return
		default:
			sel := v.list.SelectedItem()
			if sel == nil {
				return
			}
			svc := sel.(serviceItem).service
			if svc == nil {
				return
			}
			var b strings.Builder
			fmt.Fprintf(&b, "%s\n\n", titleStyle.Render("Confirm Scale "+svc.Name))
			fmt.Fprintf(&b, "  %d → %d tasks\n\n", svc.DesiredCount, v.scaleCount)
			if v.scaleCount == 0 {
				fmt.Fprintf(&b, "  %s\n\n", warnStyle.Render("⚠ This will stop all running tasks!"))
			}
			fmt.Fprintf(&b, "  %s\n", helpStyle.Render("enter confirm • esc cancel"))
			v.detail.SetContent(b.String())
			return
		}
	}

	if v.scaling {
		sel := v.list.SelectedItem()
		if sel == nil {
			return
		}
		svc := sel.(serviceItem).service
		if svc == nil {
			return
		}
		v.detail.SetContent(fmt.Sprintf(
			"%s\n\n  Current desired count: %d\n\n  New desired count: %s\n\n  %s",
			titleStyle.Render("Scale "+svc.Name),
			svc.DesiredCount,
			v.scaleInput.View(),
			helpStyle.Render("enter confirm • esc cancel"),
		))
		return
	}

	if v.showEnvVars && v.envVars != nil {
		v.renderEnvVars(titleStyle)
		return
	}

	sel := v.list.SelectedItem()
	if sel == nil {
		v.detail.SetContent("  No items")
		return
	}
	si := sel.(serviceItem)
	if si.service == nil {
		v.detail.SetContent(fmt.Sprintf("%s\n\n  %s", titleStyle.Render(si.name), helpStyle.Render("Loading details...")))
		return
	}
	v.renderServiceDetail(*si.service, titleStyle, labelStyle, helpStyle)
}

func (v *View) renderServiceDetail(s ecsaws.Service, titleStyle, labelStyle, helpStyle lipgloss.Style) {
	region := v.client.Region()
	link := fmt.Sprintf("https://%s.console.aws.amazon.com/ecs/home?region=%s#/clusters/%s/services/%s/tasks",
		region, region, v.clusterName, s.Name)

	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", titleStyle.Render(s.Name))
	kv(&b, labelStyle, "Status", s.Status)
	kv(&b, labelStyle, "Launch Type", s.LaunchType)
	kv(&b, labelStyle, "Task Definition", s.TaskDefinition)
	kv(&b, labelStyle, "Desired Count", fmt.Sprintf("%d", s.DesiredCount))
	kv(&b, labelStyle, "Running Count", fmt.Sprintf("%d", s.RunningCount))
	kv(&b, labelStyle, "Pending Count", fmt.Sprintf("%d", s.PendingCount))

	if s.CreatedAt != nil {
		kv(&b, labelStyle, "Created At", s.CreatedAt.Local().Format("2006-01-02 15:04:05"))
	}

	if metrics, ok := v.metricsMap[s.Name]; ok && metrics.HasData {
		fmt.Fprintf(&b, "\n%s\n", titleStyle.Render("Metrics (1h)"))
		if len(metrics.CPU) > 0 {
			last := metrics.CPU[len(metrics.CPU)-1]
			fmt.Fprintf(&b, "  CPU  %s %5.1f%%\n", sparkline(metrics.CPU), last)
		}
		if len(metrics.Mem) > 0 {
			last := metrics.Mem[len(metrics.Mem)-1]
			fmt.Fprintf(&b, "  Mem  %s %5.1f%%\n", sparkline(metrics.Mem), last)
		}
	} else if _, ok := v.metricsMap[s.Name]; !ok {
		fmt.Fprintf(&b, "\n  %s\n", helpStyle.Render("Loading metrics..."))
	}

	maxW := v.width - v.width*2/5 - 8
	if maxW > 0 && len(link) > maxW {
		link = link[:maxW] + "…"
	}
	fmt.Fprintf(&b, "\n  Console:\n  %s\n", link)
	v.detail.SetContent(b.String())
}

func (v *View) renderEnvVars(titleStyle lipgloss.Style) {
	var b strings.Builder
	fmt.Fprintf(&b, "%s\n", titleStyle.Render("Environment Variables"))
	for _, cd := range v.envVars {
		fmt.Fprintf(&b, "\n%s\n", lipgloss.NewStyle().Bold(true).PaddingLeft(1).Render(cd.Name))
		if len(cd.EnvVars) == 0 {
			fmt.Fprintf(&b, "  (no environment variables)\n")
			continue
		}
		maxLen := 0
		for _, ev := range cd.EnvVars {
			if len(ev.Name) > maxLen {
				maxLen = len(ev.Name)
			}
		}
		for _, ev := range cd.EnvVars {
			fmt.Fprintf(&b, "  %-*s  %s\n", maxLen, ev.Name, ev.Value)
		}
	}
	v.detail.SetContent(b.String())
}

func kv(b *strings.Builder, labelStyle lipgloss.Style, key, val string) {
	label := labelStyle.Render(fmt.Sprintf("  %-22s", key))
	fmt.Fprintf(b, "%s %s\n", label, val)
}

func sparkline(vals []float64) string {
	blocks := []rune("▁▂▃▄▅▆▇█")
	if len(vals) == 0 {
		return ""
	}
	min, max := vals[0], vals[0]
	for _, v := range vals {
		if v < min {
			min = v
		}
		if v > max {
			max = v
		}
	}
	padding := (max - min) * 0.2
	if padding < 0.5 {
		padding = 0.5
	}
	min -= padding
	if min < 0 {
		min = 0
	}
	max += padding
	rng := max - min
	out := make([]rune, len(vals))
	for i, v := range vals {
		idx := int((v - min) / rng * float64(len(blocks)-1))
		if idx >= len(blocks) {
			idx = len(blocks) - 1
		}
		if idx < 0 {
			idx = 0
		}
		out[i] = blocks[idx]
	}
	return string(out)
}

