package tasks

import (
	"context"
	"fmt"
	"strings"
	"time"

	tea "charm.land/bubbletea/v2"
	"charm.land/bubbles/v2/list"
	"charm.land/bubbles/v2/viewport"
	"charm.land/lipgloss/v2"

	ecsaws "github.com/ron/ecsx/internal/aws"
	"github.com/ron/ecsx/internal/ui/messages"
)

// View is the tasks list view with a detail pane.
type View struct {
	client      ecsaws.ECSClient
	list        list.Model
	detail      viewport.Model
	clusterName string
	serviceName string

	// Env vars state
	showEnvVars bool
	envVars     []ecsaws.ContainerDefinition

	// Confirm state
	confirming    bool
	confirmAction string // "stop"

	focused bool
	width   int
	height  int
}

// New creates a new tasks view.
func New(client ecsaws.ECSClient) *View {
	l := list.New(nil, list.NewDefaultDelegate(), 0, 0)
	l.Title = "Tasks"
	l.SetShowStatusBar(false)
	l.SetShowHelp(false)
	l.SetFilteringEnabled(true)

	return &View{
		client:  client,
		list:    l,
		detail:  viewport.New(),
		focused: true,
	}
}

func (v *View) Init() tea.Cmd {
	return nil
}

func (v *View) Update(msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case messages.TasksLoaded:
		return v.handleTasksLoaded(msg, false)

	case messages.TaskEC2Resolved:
		return v.handleTaskEC2Resolved(msg)

	case messages.EnvVarsLoaded:
		v.showEnvVars = true
		v.envVars = msg.Containers
		v.updateDetail()
		return nil

	case messages.TaskStopped:
		return v.loadTasks()

	case tea.KeyPressMsg:
		if v.confirming {
			return v.handleConfirmKey(msg)
		}
		if v.list.FilterState() == list.Filtering {
			var cmd tea.Cmd
			v.list, cmd = v.list.Update(msg)
			return cmd
		}

		switch msg.String() {
		case "enter":
			return v.handleEnter()
		case "esc":
			return v.handleEsc()
		case "e":
			return v.handleEnvVars()
		case "x":
			return v.handleStopTask()
		case "l":
			return v.handleLogs()
		case "y":
			if v.showEnvVars {
				return v.handleYank()
			}
		}
	}

	// Delegate to list for navigation
	prevName := ""
	if sel := v.list.SelectedItem(); sel != nil {
		prevName = sel.FilterValue()
	}
	var cmd tea.Cmd
	v.list, cmd = v.list.Update(msg)
	curName := ""
	if sel := v.list.SelectedItem(); sel != nil {
		curName = sel.FilterValue()
	}
	if curName != prevName {
		v.updateDetail()
	}
	return cmd
}

func (v *View) View() string {
	return v.list.View()
}

func (v *View) DetailView() string {
	return v.detail.View()
}

func (v *View) Focused() bool        { return v.focused }
func (v *View) SetFocused(f bool)     { v.focused = f }

func (v *View) SetSize(width, height int) {
	v.width = width
	v.height = height
	listW := width * 2 / 5
	detailW := width - listW
	v.list.SetSize(listW-2, height)
	v.detail.SetWidth(detailW - 2)
	v.detail.SetHeight(height)
}

func (v *View) SetContext(cluster, service string) {
	v.clusterName = cluster
	v.serviceName = service
	v.list.Title = fmt.Sprintf("Tasks (%s)", service)
}

func (v *View) HelpText() string {
	parts := []string{"↑↓ navigate", "/ filter", "enter select", "esc back", "e env vars", "l logs", "x stop"}
	if v.showEnvVars {
		parts = append(parts, "y yank")
	}
	parts = append(parts, "r refresh", "? help", "q quit")
	return "  " + strings.Join(parts, " • ")
}

// IsConfirming returns whether the view is in confirm mode.
func (v *View) IsConfirming() bool { return v.confirming }

// FilterState returns the current filter state of the list.
func (v *View) FilterState() list.FilterState {
	return v.list.FilterState()
}

// SetItems updates the list items, preserving selection if refreshing.
func (v *View) SetItems(tasks []ecsaws.Task, preserveSelection bool) tea.Cmd {
	prevSel := ""
	if sel := v.list.SelectedItem(); sel != nil {
		prevSel = sel.FilterValue()
	}
	items := make([]list.Item, len(tasks))
	for i, t := range tasks {
		items[i] = taskItem{t}
	}
	cmd := v.list.SetItems(items)
	if preserveSelection {
		for i, item := range items {
			if item.FilterValue() == prevSel {
				v.list.Select(i)
				break
			}
		}
	} else {
		v.list.ResetFilter()
		v.list.Select(0)
	}
	v.updateDetail()
	return tea.Batch(cmd, v.resolveTaskEC2(tasks))
}

// --- Internal handlers ---

func (v *View) handleTasksLoaded(msg messages.TasksLoaded, preserveSelection bool) tea.Cmd {
	return v.SetItems(msg.Tasks, preserveSelection)
}

func (v *View) handleTaskEC2Resolved(msg messages.TaskEC2Resolved) tea.Cmd {
	if msg.EC2Map == nil {
		return nil
	}
	items := v.list.Items()
	for i, item := range items {
		if ti, ok := item.(taskItem); ok {
			if id, found := msg.EC2Map[ti.task.ContainerInstanceID]; found {
				ti.task.EC2InstanceID = id
				items[i] = ti
			}
		}
	}
	v.list.SetItems(items)
	v.updateDetail()
	return nil
}

func (v *View) handleEnter() tea.Cmd {
	// Tasks don't drill down further in the list; enter could open logs
	return nil
}

func (v *View) handleEsc() tea.Cmd {
	if v.showEnvVars {
		v.showEnvVars = false
		v.envVars = nil
		v.updateDetail()
		return nil
	}
	return func() tea.Msg {
		return GoBackMsg{}
	}
}

func (v *View) handleEnvVars() tea.Cmd {
	if v.showEnvVars {
		v.showEnvVars = false
		v.envVars = nil
		v.updateDetail()
		return nil
	}
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	t := sel.(taskItem).task
	taskDef := t.TaskDefinition
	if taskDef == "" {
		return nil
	}
	client := v.client
	return func() tea.Msg {
		containers, err := client.DescribeTaskDefinition(context.Background(), taskDef)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.EnvVarsLoaded{Containers: containers}
	}
}

func (v *View) handleStopTask() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	t := sel.(taskItem).task
	if t.Status != "RUNNING" {
		return func() tea.Msg {
			return messages.Err{Err: fmt.Errorf("task is %s, not RUNNING", t.Status)}
		}
	}
	v.confirming = true
	v.confirmAction = "stop"
	v.updateDetail()
	return nil
}

func (v *View) handleConfirmKey(msg tea.KeyPressMsg) tea.Cmd {
	switch msg.String() {
	case "enter":
		return v.executeStopTask()
	case "esc":
		v.confirming = false
		v.confirmAction = ""
		v.updateDetail()
		return nil
	}
	return nil
}

func (v *View) executeStopTask() tea.Cmd {
	v.confirming = false
	v.confirmAction = ""
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	t := sel.(taskItem).task
	cluster := v.clusterName
	taskARN := t.ARN
	client := v.client
	return func() tea.Msg {
		err := client.StopTask(context.Background(), cluster, taskARN, "Stopped via ecsx")
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.TaskStopped{}
	}
}

func (v *View) handleLogs() tea.Cmd {
	return func() tea.Msg {
		return LogsRequestedMsg{ServiceName: v.serviceName}
	}
}

func (v *View) handleYank() tea.Cmd {
	if v.envVars == nil {
		return nil
	}
	return func() tea.Msg {
		return YankEnvVarsMsg{Containers: v.envVars}
	}
}

func (v *View) handleSSM() tea.Cmd {
	sel := v.list.SelectedItem()
	if sel == nil {
		return nil
	}
	t := sel.(taskItem).task
	if t.EC2InstanceID == "" {
		return func() tea.Msg {
			return messages.Err{Err: fmt.Errorf("no EC2 instance (task is %s)", t.LaunchType)}
		}
	}
	return func() tea.Msg {
		return SSMRequestedMsg{InstanceID: t.EC2InstanceID}
	}
}

func (v *View) loadTasks() tea.Cmd {
	client := v.client
	cluster := v.clusterName
	service := v.serviceName
	return func() tea.Msg {
		tasks, err := client.ListTasks(context.Background(), cluster, service)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.TasksLoaded{Tasks: tasks}
	}
}

func (v *View) resolveTaskEC2(tasks []ecsaws.Task) tea.Cmd {
	client := v.client
	cluster := v.clusterName
	return func() tea.Msg {
		ec2Map, err := client.ResolveTaskEC2Instances(context.Background(), cluster, tasks)
		if err != nil || ec2Map == nil {
			return messages.TaskEC2Resolved{}
		}
		return messages.TaskEC2Resolved{EC2Map: ec2Map}
	}
}

func (v *View) updateDetail() {
	titleStyle := lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("69")).PaddingLeft(1)
	labelStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("243"))
	helpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
	warnStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Bold(true).PaddingLeft(1)

	if v.confirming {
		sel := v.list.SelectedItem()
		if sel == nil {
			return
		}
		t := sel.(taskItem).task
		var b strings.Builder
		fmt.Fprintf(&b, "%s\n\n", titleStyle.Render("Stop Task"))
		fmt.Fprintf(&b, "  Task: %s\n\n", t.ID)
		fmt.Fprintf(&b, "  %s\n\n", warnStyle.Render("⚠ This will stop the task immediately."))
		fmt.Fprintf(&b, "  %s\n", helpStyle.Render("enter confirm • esc cancel"))
		v.detail.SetContent(b.String())
		return
	}

	if v.showEnvVars && v.envVars != nil {
		v.renderEnvVars(titleStyle)
		return
	}

	sel := v.list.SelectedItem()
	if sel == nil {
		v.detail.SetContent("  No items")
		return
	}
	v.renderTaskDetail(sel.(taskItem).task, titleStyle, labelStyle)
}

func (v *View) renderTaskDetail(t ecsaws.Task, titleStyle, labelStyle lipgloss.Style) {
	region := v.client.Region()
	taskLink := fmt.Sprintf("https://%s.console.aws.amazon.com/ecs/home?region=%s#/clusters/%s/tasks/%s",
		region, region, v.clusterName, t.ID)

	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", titleStyle.Render("Task "+t.ID[:min(12, len(t.ID))]))
	kv(&b, labelStyle, "Task ID", t.ID)
	kv(&b, labelStyle, "Status", t.Status)
	kv(&b, labelStyle, "Desired Status", t.DesiredStatus)
	kv(&b, labelStyle, "Health Status", t.HealthStatus)
	kv(&b, labelStyle, "Launch Type", t.LaunchType)
	kv(&b, labelStyle, "Task Definition", t.TaskDefinition)
	if t.Group != "" {
		kv(&b, labelStyle, "Group", t.Group)
	}
	if t.CPU != "" {
		kv(&b, labelStyle, "CPU / Memory", t.CPU+" / "+t.Memory)
	}
	if t.StartedAt != nil {
		kv(&b, labelStyle, "Started At", t.StartedAt.Local().Format("2006-01-02 15:04:05"))
		kv(&b, labelStyle, "Uptime", formatDuration(time.Since(*t.StartedAt)))
	}
	if t.CreatedAt != nil {
		kv(&b, labelStyle, "Created At", t.CreatedAt.Local().Format("2006-01-02 15:04:05"))
	}
	if t.StoppedAt != nil {
		kv(&b, labelStyle, "Stopped At", t.StoppedAt.Local().Format("2006-01-02 15:04:05"))
	}
	if t.StoppedReason != "" {
		kv(&b, labelStyle, "Stopped Reason", t.StoppedReason)
	}

	if t.LaunchType == "EC2" {
		if t.EC2InstanceID != "" {
			kv(&b, labelStyle, "EC2 Instance", t.EC2InstanceID)
			ec2Link := fmt.Sprintf("https://%s.console.aws.amazon.com/ec2/v2/home?region=%s#Instances:instanceId=%s",
				region, region, t.EC2InstanceID)
			maxW := v.width - v.width*2/5 - 8
			if maxW > 0 && len(ec2Link) > maxW {
				ec2Link = ec2Link[:maxW] + "…"
			}
			fmt.Fprintf(&b, "\n  EC2 Console:\n  %s\n", ec2Link)
		}
	} else {
		if t.PrivateIP != "" {
			kv(&b, labelStyle, "Private IP", t.PrivateIP)
		}
		if t.PublicIP != "" {
			kv(&b, labelStyle, "Public IP", t.PublicIP)
		}
	}

	maxW := v.width - v.width*2/5 - 8
	if maxW > 0 && len(taskLink) > maxW {
		taskLink = taskLink[:maxW] + "…"
	}
	fmt.Fprintf(&b, "\n  Task Console:\n  %s\n", taskLink)

	if len(t.Containers) > 0 {
		fmt.Fprintf(&b, "\n%s\n", titleStyle.Render("Containers"))
		for _, c := range t.Containers {
			fmt.Fprintf(&b, "\n  %s\n", lipgloss.NewStyle().Bold(true).Render(c.Name))
			fmt.Fprintf(&b, "    Status: %s\n", c.Status)
			if c.HealthStatus != "" && c.HealthStatus != "UNKNOWN" {
				fmt.Fprintf(&b, "    Health: %s\n", c.HealthStatus)
			}
			if c.Image != "" {
				fmt.Fprintf(&b, "    Image: %s\n", c.Image)
			}
			if c.ExitCode != nil {
				fmt.Fprintf(&b, "    Exit Code: %d\n", *c.ExitCode)
			}
			if c.Reason != "" {
				fmt.Fprintf(&b, "    Reason: %s\n", c.Reason)
			}
			for _, nb := range c.NetworkBindings {
				fmt.Fprintf(&b, "    Port: %d→%d (%s)\n", nb.ContainerPort, nb.HostPort, nb.Protocol)
			}
		}
	}
	v.detail.SetContent(b.String())
}

func (v *View) renderEnvVars(titleStyle lipgloss.Style) {
	var b strings.Builder
	fmt.Fprintf(&b, "%s\n", titleStyle.Render("Environment Variables"))
	for _, cd := range v.envVars {
		fmt.Fprintf(&b, "\n%s\n", lipgloss.NewStyle().Bold(true).PaddingLeft(1).Render(cd.Name))
		if len(cd.EnvVars) == 0 {
			fmt.Fprintf(&b, "  (no environment variables)\n")
			continue
		}
		maxLen := 0
		for _, ev := range cd.EnvVars {
			if len(ev.Name) > maxLen {
				maxLen = len(ev.Name)
			}
		}
		for _, ev := range cd.EnvVars {
			fmt.Fprintf(&b, "  %-*s  %s\n", maxLen, ev.Name, ev.Value)
		}
	}
	v.detail.SetContent(b.String())
}

func kv(b *strings.Builder, labelStyle lipgloss.Style, key, val string) {
	label := labelStyle.Render(fmt.Sprintf("  %-22s", key))
	fmt.Fprintf(b, "%s %s\n", label, val)
}

func formatDuration(d time.Duration) string {
	d = d.Round(time.Second)
	days := int(d.Hours()) / 24
	hours := int(d.Hours()) % 24
	mins := int(d.Minutes()) % 60
	if days > 0 {
		return fmt.Sprintf("%dd%dh", days, hours)
	}
	if hours > 0 {
		return fmt.Sprintf("%dh%dm", hours, mins)
	}
	return fmt.Sprintf("%dm", mins)
}

