	if i.task.StartedAt != nil {
		desc += fmt.Sprintf(" up %s", formatDuration(time.Since(*i.task.StartedAt)))
	}
	if i.task.HealthStatus != "" && i.task.HealthStatus != "UNKNOWN" {
		desc += fmt.Sprintf(" [%s]", i.task.HealthStatus)
	}
	return desc
}
