// New creates a new logs view.
func New(client ecsaws.ECSClient) *View {
	return &View{
		client:        client,
		detail:        viewport.New(),
		logDetailView: viewport.New(),
		focused:       true,
	}
}

func (v *View) Init() tea.Cmd {
	return nil
}

// StartTail begins tailing logs for the given log group and stream prefix.
func (v *View) StartTail(logGroup, streamPrefix, filter string) tea.Cmd {
	v.stopLogTail()

	v.logGroup = logGroup
	v.logStreamPrefix = streamPrefix
	v.logFilter = filter
	v.logPinned = false
	v.inDetailMode = false
	v.logLines = []ecsaws.LogEvent{}

	// Pre-fill with historical logs
	if events, err := v.client.FetchRecentLogs(context.Background(), logGroup, streamPrefix, filter, time.Now().Add(-5*time.Minute), nil); err == nil {
		v.logLines = events
	}

	ctx, cancel := context.WithCancel(context.Background())
	ch, err := v.client.TailLogs(ctx, logGroup, streamPrefix, filter)
	if err != nil {
		cancel()
		return func() tea.Msg {
			return messages.Err{Err: err}
		}
	}
	v.logCancel = cancel
	v.logCh = ch
	v.updateDetail()
	v.detail.GotoBottom()
	return v.waitForLogEvent()
}

// StopTail stops the current log tail.
func (v *View) StopTail() {
	v.stopLogTail()
	v.logFilter = ""
	v.logGrep = ""
	v.logGrepRe = nil
	v.logGroup = ""
	v.logStreamPrefix = ""
}

func (v *View) Update(msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case messages.LogEvent:
		v.logLines = append(v.logLines, msg.Event)
		if len(v.logLines) > 1000 {
			v.logLines = v.logLines[len(v.logLines)-1000:]
		}
		if !v.inDetailMode {
			v.updateDetail()
			if !v.logFiltering && !v.logGrepping && !v.logPinned {
				v.detail.GotoBottom()
			}
		}
		return v.waitForLogEvent()

	case messages.LogError:
		return func() tea.Msg { return messages.Err{Err: msg.Err} }

	case tea.KeyPressMsg:
		if v.logFiltering {
			return v.handleFilterKey(msg)
		}
		if v.logGrepping {
			return v.handleGrepKey(msg)
		}
		if v.inDetailMode {
			return v.handleDetailKey(msg)
		}
		return v.handleNormalKey(msg)
	}

	return nil
}

func (v *View) View() string {
	return v.detail.View()
}

func (v *View) DetailView() string {
	if v.inDetailMode {
		return v.logDetailView.View()
	}
	return ""
}

func (v *View) InDetailMode() bool   { return v.inDetailMode }
func (v *View) Focused() bool        { return v.focused }
func (v *View) SetFocused(f bool)    { v.focused = f }
func (v *View) IsFiltering() bool    { return v.logFiltering }
func (v *View) IsGrepping() bool     { return v.logGrepping }

func (v *View) SetSize(width, height int) {
	v.width = width
	v.height = height
	v.detail.SetWidth(width - 2)
	v.detail.SetHeight(height)
	v.logDetailView.SetWidth(width - 2)
	v.logDetailView.SetHeight(height)
}

// SetDetailSizes sets the sizes for the split detail mode.
func (v *View) SetDetailSizes(topW, topH, botW, botH int) {
	v.detail.SetWidth(topW)
	v.detail.SetHeight(topH)
	v.logDetailView.SetWidth(botW)
	v.logDetailView.SetHeight(botH)
}

func (v *View) HelpText() string {
	parts := []string{"esc back", "↑↓ scroll", "e editor", "f level:" + v.logLevel.String(), "g grep", "/ filter", "enter browse"}
	if v.logPinned {
		parts = append(parts, "end resume")
	}
	parts = append(parts, "? help", "q quit")
	return "  " + strings.Join(parts, " • ")
}

// --- Key handlers ---

func (v *View) handleNormalKey(msg tea.KeyPressMsg) tea.Cmd {
	switch msg.String() {
	case "esc":
		return func() tea.Msg { return GoBackMsg{} }
	case "enter":
		filtered := v.filteredLogLines()
		if len(filtered) == 0 {
			return nil
		}
		v.logSnapshot = filtered
		v.logCursor = len(filtered) - 1
		v.inDetailMode = true
		v.updateDetail()
		v.renderLogDetail()
		v.scrollSnapshotToCursor()
		return nil
	case "e":
		return v.openInEditor()
	case "f":
		v.logLevel = v.logLevel.Toggle()
		v.updateDetail()
		v.detail.GotoBottom()
		return nil
	case "g":
		v.logGrepping = true
		ti := textinput.New()
		ti.Placeholder = "regex pattern"
		ti.SetValue(v.logGrep)
		ti.SetWidth(40)
		v.logGrepInput = ti
		cmd := v.logGrepInput.Focus()
		v.updateDetail()
		v.detail.GotoTop()
		return cmd
	case "/":
		v.logFiltering = true
		ti := textinput.New()
		ti.Placeholder = "filter pattern"
		ti.SetValue(v.logFilter)
		ti.SetWidth(40)
		v.logFilterInput = ti
		cmd := v.logFilterInput.Focus()
		v.updateDetail()
		v.detail.GotoTop()
		return cmd
	case "up", "k", "pgup", "home":
		v.logPinned = true
		var cmd tea.Cmd
		v.detail, cmd = v.detail.Update(msg)
		return cmd
	case "down", "j", "pgdown":
		var cmd tea.Cmd
		v.detail, cmd = v.detail.Update(msg)
		v.logPinned = !v.detail.AtBottom()
		return cmd
	case "end":
		v.logPinned = false
		v.detail.GotoBottom()
		return nil
	}
	return nil
}

func (v *View) handleDetailKey(msg tea.KeyPressMsg) tea.Cmd {
	switch msg.String() {
	case "esc":
		v.inDetailMode = false
		v.logSnapshot = nil
		v.updateDetail()
		if !v.logPinned {
			v.detail.GotoBottom()
		}
		return nil
	case "up", "k":
		v.logCursor--
		if v.logCursor < 0 {
			v.logCursor = 0
		}
		v.updateDetail()
		v.renderLogDetail()
		v.scrollSnapshotToCursor()
		return nil
	case "down", "j":
		v.logCursor++
		if v.logCursor >= len(v.logSnapshot) {
			v.logCursor = len(v.logSnapshot) - 1
		}
		v.updateDetail()
		v.renderLogDetail()
		v.scrollSnapshotToCursor()
		return nil
	case "pgup":
		v.logCursor -= 10
		if v.logCursor < 0 {
			v.logCursor = 0
		}
		v.updateDetail()
		v.renderLogDetail()
		v.scrollSnapshotToCursor()
		return nil
	case "pgdown":
		v.logCursor += 10
		if v.logCursor >= len(v.logSnapshot) {
			v.logCursor = len(v.logSnapshot) - 1
		}
		v.updateDetail()
		v.renderLogDetail()
		v.scrollSnapshotToCursor()
		return nil
	case "home":
		v.logCursor = 0
		v.updateDetail()
		v.renderLogDetail()
		v.scrollSnapshotToCursor()
		return nil
	case "end":
		v.logCursor = len(v.logSnapshot) - 1
		v.updateDetail()
		v.renderLogDetail()
		v.scrollSnapshotToCursor()
		return nil
	}
	return nil
}

func (v *View) handleFilterKey(msg tea.KeyPressMsg) tea.Cmd {
	switch msg.String() {
	case "enter":
		v.logFilter = v.logFilterInput.Value()
		v.logFiltering = false
		return v.StartTail(v.logGroup, v.logStreamPrefix, v.logFilter)
	case "esc":
		v.logFiltering = false
		v.updateDetail()
		return nil
	}
	var cmd tea.Cmd
	v.logFilterInput, cmd = v.logFilterInput.Update(msg)
	v.updateDetail()
	return cmd
}

func (v *View) handleGrepKey(msg tea.KeyPressMsg) tea.Cmd {
	switch msg.String() {
	case "enter":
		pattern := v.logGrepInput.Value()
		if pattern == "" {
			v.logGrep = ""
			v.logGrepRe = nil
		} else {
			re, err := regexp.Compile(pattern)
			if err != nil {
				v.logGrepping = false
				v.updateDetail()
				return func() tea.Msg {
					return messages.Err{Err: fmt.Errorf("invalid regex: %w", err)}
				}
			}
			v.logGrep = pattern
			v.logGrepRe = re
		}
		v.logGrepping = false
		v.updateDetail()
		v.detail.GotoBottom()
		return nil
	case "esc":
		v.logGrepping = false
		v.updateDetail()
		return nil
	}
	var cmd tea.Cmd
	v.logGrepInput, cmd = v.logGrepInput.Update(msg)
	v.updateDetail()
	return cmd
}

// --- Helpers ---

func (v *View) stopLogTail() {
	if v.logCancel != nil {
		v.logCancel()
		v.logCancel = nil
	}
	v.logCh = nil
	v.logLines = nil
}

func (v *View) waitForLogEvent() tea.Cmd {
	if v.logCh == nil {
		return nil
	}
	ch := v.logCh
	return func() tea.Msg {
		ev, ok := <-ch
		if !ok {
			return nil
		}
		return messages.LogEvent{Event: ev}
	}
}

func (v *View) filteredLogLines() []ecsaws.LogEvent {
	var out []ecsaws.LogEvent
	for _, ev := range v.logLines {
		if !v.logLevel.Matches(ev.Message) {
			continue
		}
		if v.logGrepRe != nil && !v.logGrepRe.MatchString(ev.Message) {
			continue
		}
		out = append(out, ev)
	}
	return out
}

func (v *View) scrollSnapshotToCursor() {
	line := v.logCursor + 2
	viewH := v.detail.Height()
	if viewH < 1 {
		viewH = 1
	}
	top := v.detail.YOffset()
	if line < top {
		v.detail.SetYOffset(line)
	} else if line >= top+viewH {
		v.detail.SetYOffset(line - viewH + 1)
	}
}

func (v *View) openInEditor() tea.Cmd {
	lines := v.filteredLogLines()
	f, err := os.CreateTemp("", "ecsx-logs-*.log")
	if err != nil {
		return func() tea.Msg { return messages.EditorFinished{Err: err} }
	}
	for _, ev := range lines {
		fmt.Fprintf(f, "%s %s %s\n", ev.Timestamp.Local().Format("2006-01-02 15:04:05.000"), ev.Stream, ansiRe.ReplaceAllString(ev.Message, ""))
	}
	f.Close()

	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = "vi"
	}
	c := exec.Command(editor, f.Name())
	return tea.ExecProcess(c, func(err error) tea.Msg {
		return messages.EditorFinished{Err: err, Path: f.Name()}
	})
}

func (v *View) updateDetail() {
	titleStyle := lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("69")).PaddingLeft(1)
	helpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))

	if v.inDetailMode {
		v.renderLogSnapshot(titleStyle)
		return
	}

	var b strings.Builder
	levelTag := ""
	if v.logLevel != logs.LevelAll {
		levelTag = " [" + v.logLevel.String() + "]"
	}
	if v.logGrepping {
		fmt.Fprintf(&b, "%s  %s\n\n", titleStyle.Render("Grep:"), v.logGrepInput.View())
	} else if v.logFiltering {
		fmt.Fprintf(&b, "%s  %s\n\n", titleStyle.Render("Filter:"), v.logFilterInput.View())
	} else {
		tailStatus := "tailing"
		if v.logPinned {
			tailStatus = "paused"
		}
		tags := "Logs (" + tailStatus + ")" + levelTag
		var hints []string
		if v.logFilter != "" {
			hints = append(hints, "filter: "+v.logFilter)
		}
		if v.logGrep != "" {
			hints = append(hints, "grep: /"+v.logGrep+"/")
		}
		if len(hints) > 0 {
			fmt.Fprintf(&b, "%s %s\n\n", titleStyle.Render(tags), helpStyle.Render(strings.Join(hints, " • ")))
		} else {
			fmt.Fprintf(&b, "%s\n\n", titleStyle.Render(tags))
		}
	}
	if len(v.logLines) == 0 {
		fmt.Fprintf(&b, "  %s\n", helpStyle.Render("Waiting for log events..."))
	} else {
		streamColorMap := make(map[string]color.Color)
		colorIdx := 0
		for _, ev := range v.logLines {
			if !v.logLevel.Matches(ev.Message) {
				continue
			}
			if v.logGrepRe != nil && !v.logGrepRe.MatchString(ev.Message) {
				continue
			}
			if _, ok := streamColorMap[ev.Stream]; !ok {
				streamColorMap[ev.Stream] = logStreamColors[colorIdx%len(logStreamColors)]
				colorIdx++
			}
			sc := streamColorMap[ev.Stream]
			ts := lipgloss.NewStyle().Foreground(sc).Render(ev.Timestamp.Local().Format("15:04:05"))
			fmt.Fprintf(&b, "  %s %s\n", ts, ev.Message)
		}
	}
	v.detail.SetContent(b.String())
}

func (v *View) renderLogSnapshot(titleStyle lipgloss.Style) {
	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", titleStyle.Render(fmt.Sprintf("Log Browser (%d/%d)", v.logCursor+1, len(v.logSnapshot))))
	streamColorMap := make(map[string]color.Color)
	colorIdx := 0
	for i, ev := range v.logSnapshot {
		if _, ok := streamColorMap[ev.Stream]; !ok {
			streamColorMap[ev.Stream] = logStreamColors[colorIdx%len(logStreamColors)]
			colorIdx++
		}
		sc := streamColorMap[ev.Stream]
		ts := lipgloss.NewStyle().Foreground(sc).Render(ev.Timestamp.Local().Format("15:04:05"))
		if i == v.logCursor {
			line := fmt.Sprintf("▸ %s %s", ev.Timestamp.Local().Format("15:04:05"), ev.Message)
			fmt.Fprintf(&b, "%s\n", lipgloss.NewStyle().Bold(true).Background(lipgloss.Color("62")).Foreground(lipgloss.Color("255")).Render(line))
		} else {
			fmt.Fprintf(&b, "  %s %s\n", ts, ev.Message)
		}
	}
	v.detail.SetContent(b.String())
}

func (v *View) renderLogDetail() {
	titleStyle := lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("69")).PaddingLeft(1)
	labelStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("243"))

	if v.logCursor < 0 || v.logCursor >= len(v.logSnapshot) {
		v.logDetailView.SetContent("")
		return
	}
	ev := v.logSnapshot[v.logCursor]
	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", titleStyle.Render("Log Detail"))
	label := labelStyle.Render(fmt.Sprintf("  %-22s", "Timestamp"))
	fmt.Fprintf(&b, "%s %s\n", label, ev.Timestamp.Local().Format("2006-01-02 15:04:05.000"))
	label = labelStyle.Render(fmt.Sprintf("  %-22s", "Stream"))
	fmt.Fprintf(&b, "%s %s\n", label, ev.Stream)
	fmt.Fprintf(&b, "\n")
	msg := strings.TrimSpace(ev.Message)
	var raw json.RawMessage
	if json.Unmarshal([]byte(msg), &raw) == nil {
		if pretty, err := json.MarshalIndent(raw, "  ", "  "); err == nil {
			fmt.Fprintf(&b, "  %s\n", string(pretty))
			v.logDetailView.SetContent(b.String())
			return
		}
	}
	fmt.Fprintf(&b, "  %s\n", msg)
	v.logDetailView.SetContent(b.String())
}

