// Package shared provides common styles, helpers, and utilities
// used across ecsx TUI view packages.
package shared

import (
	"fmt"
	"image/color"
	"strings"
	"time"

	"charm.land/lipgloss/v2"
)

// Styles used across views.
var (
	PaneBorder = lipgloss.NewStyle().
			Border(lipgloss.RoundedBorder()).
			BorderForeground(lipgloss.Color("62"))
	ActiveBorder = lipgloss.NewStyle().
			Border(lipgloss.RoundedBorder()).
			BorderForeground(lipgloss.Color("69"))
	TitleStyle = lipgloss.NewStyle().
			Bold(true).
			Foreground(lipgloss.Color("69")).
			PaddingLeft(1)
	LabelStyle = lipgloss.NewStyle().
			Foreground(lipgloss.Color("243"))
	HelpStyle = lipgloss.NewStyle().
			Foreground(lipgloss.Color("241"))
	BreadcrumbStyle = lipgloss.NewStyle().
			Foreground(lipgloss.Color("69")).
			Bold(true)
	ErrorStyle = lipgloss.NewStyle().
			Foreground(lipgloss.Color("196")).
			PaddingLeft(2)
	WarnStyle = lipgloss.NewStyle().
			Foreground(lipgloss.Color("214")).
			Bold(true).
			PaddingLeft(1)
)

// LogStreamColors are the colors used for log stream timestamps.
var LogStreamColors = []color.Color{
	lipgloss.Color("69"), lipgloss.Color("212"), lipgloss.Color("114"), lipgloss.Color("208"),
	lipgloss.Color("39"), lipgloss.Color("168"), lipgloss.Color("156"), lipgloss.Color("203"),
}

// KV writes a key-value line to the builder.
func KV(b *strings.Builder, key, val string) {
	label := LabelStyle.Render(fmt.Sprintf("  %-22s", key))
	fmt.Fprintf(b, "%s %s\n", label, val)
}

// WriteLink writes a labeled link to the builder, truncating if needed.
func WriteLink(b *strings.Builder, label, url string, maxW int) {
	if maxW > 0 && len(url) > maxW {
		url = url[:maxW] + "…"
	}
	fmt.Fprintf(b, "\n  %s\n  %s\n", label, url)
}

// Sparkline renders a sparkline chart from float64 values.
func Sparkline(vals []float64) string {
	blocks := []rune("▁▂▃▄▅▆▇█")
	if len(vals) == 0 {
		return ""
	}
	min, max := vals[0], vals[0]
	for _, v := range vals {
		if v < min {
			min = v
		}
		if v > max {
			max = v
		}
	}
	padding := (max - min) * 0.2
	if padding < 0.5 {
		padding = 0.5
	}
	min -= padding
	if min < 0 {
		min = 0
	}
	max += padding
	rng := max - min
	out := make([]rune, len(vals))
	for i, v := range vals {
		idx := int((v - min) / rng * float64(len(blocks)-1))
		if idx >= len(blocks) {
			idx = len(blocks) - 1
		}
		if idx < 0 {
			idx = 0
		}
		out[i] = blocks[idx]
	}
	return string(out)
}

// FormatDuration formats a duration into a human-readable string.
func FormatDuration(d time.Duration) string {
	d = d.Round(time.Second)
	days := int(d.Hours()) / 24
	hours := int(d.Hours()) % 24
	mins := int(d.Minutes()) % 60
	if days > 0 {
		return fmt.Sprintf("%dd%dh", days, hours)
	}
	if hours > 0 {
		return fmt.Sprintf("%dh%dm", hours, mins)
	}
	return fmt.Sprintf("%dm", mins)
}

