func (v *View) updateDetail() {
	if v.confirming {
		switch v.confirmAction {
		case "deploy":
			var b strings.Builder
			fmt.Fprintf(&b, "%s\n\n", shared.TitleStyle.Render("Force New Deployment"))
			fmt.Fprintf(&b, "  Service: %s\n\n", v.scaleSvc)
			fmt.Fprintf(&b, "  %s\n\n", shared.WarnStyle.Render("⚠ This will trigger a rolling restart of all tasks."))
			fmt.Fprintf(&b, "  %s\n", shared.HelpStyle.Render("enter confirm • esc cancel"))
			v.detail.SetContent(b.String())
			return
		default:
			sel := v.list.SelectedItem()
			if sel == nil {
				return
			}
			svc := sel.(serviceItem).service
			if svc == nil {
				return
			}
			var b strings.Builder
			fmt.Fprintf(&b, "%s\n\n", shared.TitleStyle.Render("Confirm Scale "+svc.Name))
			fmt.Fprintf(&b, "  %d → %d tasks\n\n", svc.DesiredCount, v.scaleCount)
			if v.scaleCount == 0 {
				fmt.Fprintf(&b, "  %s\n\n", shared.WarnStyle.Render("⚠ This will stop all running tasks!"))
			}
			fmt.Fprintf(&b, "  %s\n", shared.HelpStyle.Render("enter confirm • esc cancel"))
			v.detail.SetContent(b.String())
			return
		}
	}

	if v.scaling {
		sel := v.list.SelectedItem()
		if sel == nil {
			return
		}
		svc := sel.(serviceItem).service
		if svc == nil {
			return
		}
		v.detail.SetContent(fmt.Sprintf(
			"%s\n\n  Current desired count: %d\n\n  New desired count: %s\n\n  %s",
			shared.TitleStyle.Render("Scale "+svc.Name),
			svc.DesiredCount,
			v.scaleInput.View(),
			shared.HelpStyle.Render("enter confirm • esc cancel"),
		))
		return
	}

	if v.showEnvVars && v.envVars != nil {
		v.renderEnvVars()
		return
	}

	sel := v.list.SelectedItem()
	if sel == nil {
		v.detail.SetContent("  No items")
		return
	}
	si := sel.(serviceItem)
	if si.service == nil {
		v.detail.SetContent(fmt.Sprintf("%s\n\n  %s", shared.TitleStyle.Render(si.name), shared.HelpStyle.Render("Loading details...")))
		return
	}
	v.renderServiceDetail(*si.service)
}

