		sel := v.list.SelectedItem()
		if sel == nil {
			return
		}
		svc := sel.(serviceItem).service
		if svc == nil {
			return
		}
		v.detail.SetContent(fmt.Sprintf(
			"%s\n\n  Current desired count: %d\n\n  New desired count: %s\n\n  %s",
			titleStyle.Render("Scale "+svc.Name),
			svc.DesiredCount,
			v.scaleInput.View(),
			helpStyle.Render("enter confirm • esc cancel"),
		))
		return
	}

	if v.showEnvVars && v.envVars != nil {
		v.renderEnvVars(titleStyle)
		return
	}

	sel := v.list.SelectedItem()
	if sel == nil {
		v.detail.SetContent("  No items")
		return
	}
	si := sel.(serviceItem)
	if si.service == nil {
		v.detail.SetContent(fmt.Sprintf("%s\n\n  %s", titleStyle.Render(si.name), helpStyle.Render("Loading details...")))
		return
	}
	v.renderServiceDetail(*si.service, titleStyle, labelStyle, helpStyle)
}

