func (v *View) renderServiceDetail(s ecsaws.Service) {
	region := v.client.Region()
	link := fmt.Sprintf("https://%s.console.aws.amazon.com/ecs/home?region=%s#/clusters/%s/services/%s/tasks",
		region, region, v.clusterName, s.Name)

	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", shared.TitleStyle.Render(s.Name))
	shared.KV(&b, "Status", s.Status)
	shared.KV(&b, "Launch Type", s.LaunchType)
	shared.KV(&b, "Task Definition", s.TaskDefinition)
	shared.KV(&b, "Desired Count", fmt.Sprintf("%d", s.DesiredCount))
	shared.KV(&b, "Running Count", fmt.Sprintf("%d", s.RunningCount))
	shared.KV(&b, "Pending Count", fmt.Sprintf("%d", s.PendingCount))

	if s.CreatedAt != nil {
		shared.KV(&b, "Created At", s.CreatedAt.Local().Format("2006-01-02 15:04:05"))
	}

	if metrics, ok := v.metricsMap[s.Name]; ok && metrics.HasData {
		fmt.Fprintf(&b, "\n%s\n", shared.TitleStyle.Render("Metrics (1h)"))
		if len(metrics.CPU) > 0 {
			last := metrics.CPU[len(metrics.CPU)-1]
			fmt.Fprintf(&b, "  CPU  %s %5.1f%%\n", shared.Sparkline(metrics.CPU), last)
		}
		if len(metrics.Mem) > 0 {
			last := metrics.Mem[len(metrics.Mem)-1]
			fmt.Fprintf(&b, "  Mem  %s %5.1f%%\n", shared.Sparkline(metrics.Mem), last)
		}
	} else if _, ok := v.metricsMap[s.Name]; !ok {
		fmt.Fprintf(&b, "\n  %s\n", shared.HelpStyle.Render("Loading metrics..."))
	}

	maxW := v.width - v.width*2/5 - 8
	shared.WriteLink(&b, "Console:", link, maxW)
	v.detail.SetContent(b.String())
}

