func (v *View) updateDetail() {
	if v.confirming {
		sel := v.list.SelectedItem()
		if sel == nil {
			return
		}
		t := sel.(taskItem).task
		var b strings.Builder
		fmt.Fprintf(&b, "%s\n\n", shared.TitleStyle.Render("Stop Task"))
		fmt.Fprintf(&b, "  Task: %s\n\n", t.ID)
		fmt.Fprintf(&b, "  %s\n\n", shared.WarnStyle.Render("⚠ This will stop the task immediately."))
		fmt.Fprintf(&b, "  %s\n", shared.HelpStyle.Render("enter confirm • esc cancel"))
		v.detail.SetContent(b.String())
		return
	}

	if v.showEnvVars && v.envVars != nil {
		v.renderEnvVars()
		return
	}

	sel := v.list.SelectedItem()
	if sel == nil {
		v.detail.SetContent("  No items")
		return
	}
	v.renderTaskDetail(sel.(taskItem).task)
}

