func (v *View) renderTaskDetail(t ecsaws.Task) {
	region := v.client.Region()
	taskLink := fmt.Sprintf("https://%s.console.aws.amazon.com/ecs/home?region=%s#/clusters/%s/tasks/%s",
		region, region, v.clusterName, t.ID)

	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", shared.TitleStyle.Render("Task "+t.ID[:min(12, len(t.ID))]))
	shared.KV(&b, "Task ID", t.ID)
	shared.KV(&b, "Status", t.Status)
	shared.KV(&b, "Desired Status", t.DesiredStatus)
	shared.KV(&b, "Health Status", t.HealthStatus)
	shared.KV(&b, "Launch Type", t.LaunchType)
	shared.KV(&b, "Task Definition", t.TaskDefinition)
	if t.Group != "" {
		shared.KV(&b, "Group", t.Group)
	}
	if t.CPU != "" {
		shared.KV(&b, "CPU / Memory", t.CPU+" / "+t.Memory)
	}
	if t.StartedAt != nil {
		shared.KV(&b, "Started At", t.StartedAt.Local().Format("2006-01-02 15:04:05"))
		shared.KV(&b, "Uptime", shared.FormatDuration(time.Since(*t.StartedAt)))
	}
	if t.CreatedAt != nil {
		shared.KV(&b, "Created At", t.CreatedAt.Local().Format("2006-01-02 15:04:05"))
	}
	if t.StoppedAt != nil {
		shared.KV(&b, "Stopped At", t.StoppedAt.Local().Format("2006-01-02 15:04:05"))
	}
	if t.StoppedReason != "" {
		shared.KV(&b, "Stopped Reason", t.StoppedReason)
	}

	maxW := v.width - v.width*2/5 - 8

	if t.LaunchType == "EC2" {
		if t.EC2InstanceID != "" {
			shared.KV(&b, "EC2 Instance", t.EC2InstanceID)
			ec2Link := fmt.Sprintf("https://%s.console.aws.amazon.com/ec2/v2/home?region=%s#Instances:instanceId=%s",
				region, region, t.EC2InstanceID)
			shared.WriteLink(&b, "EC2 Console:", ec2Link, maxW)
		}
	} else {
		if t.PrivateIP != "" {
			shared.KV(&b, "Private IP", t.PrivateIP)
		}
		if t.PublicIP != "" {
			shared.KV(&b, "Public IP", t.PublicIP)
		}
	}

	shared.WriteLink(&b, "Task Console:", taskLink, maxW)

	if len(t.Containers) > 0 {
		fmt.Fprintf(&b, "\n%s\n", shared.TitleStyle.Render("Containers"))
		for _, c := range t.Containers {
			fmt.Fprintf(&b, "\n  %s\n", lipgloss.NewStyle().Bold(true).Render(c.Name))
			fmt.Fprintf(&b, "    Status: %s\n", c.Status)
			if c.HealthStatus != "" && c.HealthStatus != "UNKNOWN" {
				fmt.Fprintf(&b, "    Health: %s\n", c.HealthStatus)
			}
			if c.Image != "" {
				fmt.Fprintf(&b, "    Image: %s\n", c.Image)
			}
			if c.ExitCode != nil {
				fmt.Fprintf(&b, "    Exit Code: %d\n", *c.ExitCode)
			}
			if c.Reason != "" {
				fmt.Fprintf(&b, "    Reason: %s\n", c.Reason)
			}
			for _, nb := range c.NetworkBindings {
				fmt.Fprintf(&b, "    Port: %d→%d (%s)\n", nb.ContainerPort, nb.HostPort, nb.Protocol)
			}
		}
	}
	v.detail.SetContent(b.String())
}

