func (v *View) renderTaskDetail(t ecsaws.Task, titleStyle, labelStyle lipgloss.Style) {
	region := v.client.Region()
	taskLink := fmt.Sprintf("https://%s.console.aws.amazon.com/ecs/home?region=%s#/clusters/%s/tasks/%s",
		region, region, v.clusterName, t.ID)

	var b strings.Builder
	fmt.Fprintf(&b, "%s\n\n", titleStyle.Render("Task "+t.ID[:min(12, len(t.ID))]))
	kv(&b, labelStyle, "Task ID", t.ID)
	kv(&b, labelStyle, "Status", t.Status)
	kv(&b, labelStyle, "Desired Status", t.DesiredStatus)
	kv(&b, labelStyle, "Health Status", t.HealthStatus)
	kv(&b, labelStyle, "Launch Type", t.LaunchType)
	kv(&b, labelStyle, "Task Definition", t.TaskDefinition)
	if t.Group != "" {
		kv(&b, labelStyle, "Group", t.Group)
	}
	if t.CPU != "" {
		kv(&b, labelStyle, "CPU / Memory", t.CPU+" / "+t.Memory)
	}
	if t.StartedAt != nil {
		kv(&b, labelStyle, "Started At", t.StartedAt.Local().Format("2006-01-02 15:04:05"))
		kv(&b, labelStyle, "Uptime", formatDuration(time.Since(*t.StartedAt)))
	}
	if t.CreatedAt != nil {
		kv(&b, labelStyle, "Created At", t.CreatedAt.Local().Format("2006-01-02 15:04:05"))
	}
	if t.StoppedAt != nil {
		kv(&b, labelStyle, "Stopped At", t.StoppedAt.Local().Format("2006-01-02 15:04:05"))
	}
	if t.StoppedReason != "" {
		kv(&b, labelStyle, "Stopped Reason", t.StoppedReason)
	}

	if t.LaunchType == "EC2" {
		if t.EC2InstanceID != "" {
			kv(&b, labelStyle, "EC2 Instance", t.EC2InstanceID)
			ec2Link := fmt.Sprintf("https://%s.console.aws.amazon.com/ec2/v2/home?region=%s#Instances:instanceId=%s",
				region, region, t.EC2InstanceID)
			maxW := v.width - v.width*2/5 - 8
			if maxW > 0 && len(ec2Link) > maxW {
				ec2Link = ec2Link[:maxW] + "…"
			}
			fmt.Fprintf(&b, "\n  EC2 Console:\n  %s\n", ec2Link)
		}
	} else {
		if t.PrivateIP != "" {
			kv(&b, labelStyle, "Private IP", t.PrivateIP)
		}
		if t.PublicIP != "" {
			kv(&b, labelStyle, "Public IP", t.PublicIP)
		}
	}

	maxW := v.width - v.width*2/5 - 8
	if maxW > 0 && len(taskLink) > maxW {
		taskLink = taskLink[:maxW] + "…"
	}
	fmt.Fprintf(&b, "\n  Task Console:\n  %s\n", taskLink)

	if len(t.Containers) > 0 {
		fmt.Fprintf(&b, "\n%s\n", titleStyle.Render("Containers"))
		for _, c := range t.Containers {
			fmt.Fprintf(&b, "\n  %s\n", lipgloss.NewStyle().Bold(true).Render(c.Name))
			fmt.Fprintf(&b, "    Status: %s\n", c.Status)
			if c.HealthStatus != "" && c.HealthStatus != "UNKNOWN" {
				fmt.Fprintf(&b, "    Health: %s\n", c.HealthStatus)
			}
			if c.Image != "" {
				fmt.Fprintf(&b, "    Image: %s\n", c.Image)
			}
			if c.ExitCode != nil {
				fmt.Fprintf(&b, "    Exit Code: %d\n", *c.ExitCode)
			}
			if c.Reason != "" {
				fmt.Fprintf(&b, "    Reason: %s\n", c.Reason)
			}
			for _, nb := range c.NetworkBindings {
				fmt.Fprintf(&b, "    Port: %d→%d (%s)\n", nb.ContainerPort, nb.HostPort, nb.Protocol)
			}
		}
	}
	v.detail.SetContent(b.String())
}

