func (v *View) renderEnvVars() {
	var b strings.Builder
	fmt.Fprintf(&b, "%s\n", shared.TitleStyle.Render("Environment Variables"))
	for _, cd := range v.envVars {
		fmt.Fprintf(&b, "\n%s\n", lipgloss.NewStyle().Bold(true).PaddingLeft(1).Render(cd.Name))
		if len(cd.EnvVars) == 0 {
			fmt.Fprintf(&b, "  (no environment variables)\n")
