func (v *View) updateDetail() {
	if v.inDetailMode {
		v.renderLogSnapshot()
		return
	}

	var b strings.Builder
	levelTag := ""
	if v.logLevel != logs.LevelAll {
		levelTag = " [" + v.logLevel.String() + "]"
	}
	if v.logGrepping {
		fmt.Fprintf(&b, "%s  %s\n\n", shared.TitleStyle.Render("Grep:"), v.logGrepInput.View())
	} else if v.logFiltering {
		fmt.Fprintf(&b, "%s  %s\n\n", shared.TitleStyle.Render("Filter:"), v.logFilterInput.View())
	} else {
		tailStatus := "tailing"
		if v.logPinned {
			tailStatus = "paused"
		}
		tags := "Logs (" + tailStatus + ")" + levelTag
		var hints []string
		if v.logFilter != "" {
			hints = append(hints, "filter: "+v.logFilter)
		}
		if v.logGrep != "" {
			hints = append(hints, "grep: /"+v.logGrep+"/")
		}
		if len(hints) > 0 {
			fmt.Fprintf(&b, "%s %s\n\n", shared.TitleStyle.Render(tags), shared.HelpStyle.Render(strings.Join(hints, " • ")))
		} else {
			fmt.Fprintf(&b, "%s\n\n", shared.TitleStyle.Render(tags))
		}
	}
	if len(v.logLines) == 0 {
		fmt.Fprintf(&b, "  %s\n", shared.HelpStyle.Render("Waiting for log events..."))
	} else {
		streamColorMap := make(map[string]color.Color)
		colorIdx := 0
		for _, ev := range v.logLines {
			if !v.logLevel.Matches(ev.Message) {
				continue
			}
			if v.logGrepRe != nil && !v.logGrepRe.MatchString(ev.Message) {
				continue
			}
			if _, ok := streamColorMap[ev.Stream]; !ok {
				streamColorMap[ev.Stream] = logStreamColors[colorIdx%len(logStreamColors)]
				colorIdx++
			}
			sc := streamColorMap[ev.Stream]
			ts := lipgloss.NewStyle().Foreground(sc).Render(ev.Timestamp.Local().Format("15:04:05"))
			fmt.Fprintf(&b, "  %s %s\n", ts, ev.Message)
		}
	}
	v.detail.SetContent(b.String())
}

