package ui

import (
	"context"
	"fmt"
	"os"
	"strings"
	"time"

	tea "charm.land/bubbletea/v2"
	"charm.land/bubbles/v2/list"
	"charm.land/bubbles/v2/spinner"
	"charm.land/lipgloss/v2"

	ecsaws "github.com/ron/ecsx/internal/aws"
	"github.com/ron/ecsx/internal/ui/messages"
	"github.com/ron/ecsx/internal/ui/shared"
	clustersview "github.com/ron/ecsx/internal/ui/views/clusters"
	logsview "github.com/ron/ecsx/internal/ui/views/logs"
	servicesview "github.com/ron/ecsx/internal/ui/views/services"
	tasksview "github.com/ron/ecsx/internal/ui/views/tasks"
)

type activeView int

const (
	viewClustersActive activeView = iota
	viewServicesActive
	viewTasksActive
	viewLogsActive
	viewEC2Active
	viewContainerSelectActive
)

// Home is the root model that orchestrates views.
type Home struct {
	client  ecsaws.ECSClient
	spinner spinner.Model

	// Sub-views
	clusters *clustersview.View
	services *servicesview.View
	tasks    *tasksview.View
	logs     *logsview.View

	// EC2/container select (kept inline for now — small views)
	ec2List       list.Model
	containerList list.Model

	active         activeView
	initialCluster string
	clusterName    string
	serviceName    string

	showHelp    bool
	zoomed      bool
	loading     bool
	err         error
	width       int
	height      int
	autoRefresh bool
	refreshing  bool
}

func NewHome(client ecsaws.ECSClient, cluster string) Home {
	sp := spinner.New()

	return Home{
		client:         client,
		spinner:        sp,
		clusters:       clustersview.New(client),
		services:       servicesview.New(client),
		tasks:          tasksview.New(client),
		logs:           logsview.New(client),
		ec2List:        newInlineList("EC2 Instances"),
		containerList:  newInlineList("Select container"),
		loading:        true,
		initialCluster: cluster,
		clusterName:    cluster,
		autoRefresh:    true,
	}
}

func newInlineList(title string) list.Model {
	l := list.New(nil, list.NewDefaultDelegate(), 0, 0)
	l.Title = title
	l.SetShowStatusBar(false)
	l.SetShowHelp(false)
	l.SetFilteringEnabled(true)
	return l
}

const homeAutoRefreshInterval = 30 * time.Second

func homeAutoRefreshCmd() tea.Cmd {
	return tea.Tick(homeAutoRefreshInterval, func(time.Time) tea.Msg {
		return messages.AutoRefresh{}
	})
}

func (h Home) Init() tea.Cmd {
	if h.initialCluster != "" {
		return tea.Batch(h.spinner.Tick, h.loadServiceNames(h.initialCluster), homeAutoRefreshCmd())
	}
	return tea.Batch(h.spinner.Tick, h.loadClusters(), homeAutoRefreshCmd())
}

func (h Home) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		h.width = msg.Width
		h.height = msg.Height
		h.updateSizes()
		return h, nil

	case tea.KeyPressMsg:
		return h.handleKey(msg)

	case messages.ClustersLoaded:
		h.loading = false
		cmd := h.clusters.SetItems(msg.Clusters, h.refreshing)
		h.refreshing = false
		h.active = viewClustersActive
		return h, cmd

	case messages.ServiceNamesLoaded:
		h.loading = false
		h.active = viewServicesActive
		h.services.SetCluster(h.clusterName)
		cmd := h.services.SetItems(msg.Names, h.refreshing)
		h.refreshing = false
		return h, cmd

	case messages.ServiceDetailLoaded:
		cmd := h.services.Update(msg)
		return h, cmd

	case messages.ServicesLoaded:
		h.loading = false
		h.active = viewServicesActive
		cmd := h.services.Update(msg)
		return h, cmd

	case messages.TasksLoaded:
		h.loading = false
		h.active = viewTasksActive
		h.tasks.SetContext(h.clusterName, h.serviceName)
		cmd := h.tasks.SetItems(msg.Tasks, h.refreshing)
		h.refreshing = false
		return h, cmd

	case messages.TaskEC2Resolved:
		cmd := h.tasks.Update(msg)
		return h, cmd

	case messages.EnvVarsLoaded:
		h.loading = false
		switch h.active {
		case viewServicesActive:
			h.services.Update(msg)
		case viewTasksActive:
			h.tasks.Update(msg)
		}
		return h, nil

	case messages.ServiceScaled:
		h.loading = false
		return h, h.loadServiceNames(h.clusterName)

	case messages.ServiceRedeployed:
		h.loading = false
		return h, h.loadServiceNames(h.clusterName)

	case messages.TaskStopped:
		h.loading = false
		return h, h.loadTasks(h.clusterName, h.serviceName)

	case messages.MetricsLoaded:
		h.services.Update(msg)
		return h, nil

	case messages.LogEvent:
		cmd := h.logs.Update(msg)
		return h, cmd

	case messages.LogError:
		h.err = msg.Err
		return h, nil

	case messages.LogGroupFound:
		h.loading = false
		cmd := h.logs.StartTail(msg.LogGroup, msg.StreamPrefix, "")
		h.active = viewLogsActive
		h.zoomed = true
		return h, cmd

	case messages.LogGroupsFound:
		h.loading = false
		h.active = viewContainerSelectActive
		items := make([]list.Item, len(msg.Groups))
		for i, g := range msg.Groups {
			items[i] = containerLogItem{g}
		}
		cmd := h.containerList.SetItems(items)
		h.updateSizes()
		return h, cmd

	case messages.EC2InstancesLoaded:
		h.loading = false
		if len(msg.Instances) == 0 {
			h.err = fmt.Errorf("no container instances in cluster %s", h.clusterName)
			return h, nil
		}
		h.active = viewEC2Active
		items := make([]list.Item, len(msg.Instances))
		for i, inst := range msg.Instances {
			items[i] = ec2Item{inst}
		}
		cmd := h.ec2List.SetItems(items)
		h.ec2List.Title = fmt.Sprintf("EC2 Instances (%s)", h.clusterName)
		h.ec2List.Select(0)
		h.updateSizes()
		return h, cmd

	case messages.SSMTarget:
		h.loading = false
		return h, startSSMSession(msg.InstanceID, h.client.Region(), h.client.Profile())

	case messages.SSMFinished:
		if msg.Err != nil {
			h.err = msg.Err
		}
		return h, nil

	case messages.EditorFinished:
		if msg.Path != "" {
			os.Remove(msg.Path)
		}
		if msg.Err != nil {
			h.err = msg.Err
		}
		return h, nil

	case messages.AutoRefresh:
		return h.handleAutoRefresh()

	case messages.Err:
		h.loading = false
		if h.initialCluster != "" && h.active == viewClustersActive {
			h.initialCluster = ""
			h.clusterName = ""
			h.loading = true
			return h, tea.Batch(h.spinner.Tick, h.loadClusters())
		}
		h.err = msg.Err
		return h, nil

	case spinner.TickMsg:
		if h.loading {
			var cmd tea.Cmd
			h.spinner, cmd = h.spinner.Update(msg)
			return h, cmd
		}
		return h, nil

	// View-emitted navigation messages
	case servicesview.ServiceSelectedMsg:
		h.serviceName = msg.ServiceName
		h.loading = true
		return h, tea.Batch(h.spinner.Tick, h.loadTasks(h.clusterName, msg.ServiceName))

	case servicesview.GoBackMsg:
		if h.initialCluster != "" {
			return h, tea.Quit
		}
		h.clusterName = ""
		h.loading = true
		return h, tea.Batch(h.spinner.Tick, h.loadClusters())

	case servicesview.LogsRequestedMsg:
		h.loading = true
		return h, tea.Batch(h.spinner.Tick, h.findLogGroups(h.clusterName, msg.ServiceName))

	case servicesview.YankEnvVarsMsg:
		return h.yankEnvVars(msg.Containers)

	case tasksview.GoBackMsg:
		h.serviceName = ""
		h.loading = true
		return h, tea.Batch(h.spinner.Tick, h.loadServiceNames(h.clusterName))

	case tasksview.LogsRequestedMsg:
		h.loading = true
		return h, tea.Batch(h.spinner.Tick, h.findLogGroups(h.clusterName, msg.ServiceName))

	case tasksview.YankEnvVarsMsg:
		return h.yankEnvVars(msg.Containers)

	case tasksview.SSMRequestedMsg:
		return h, startSSMSession(msg.InstanceID, h.client.Region(), h.client.Profile())

	case logsview.GoBackMsg:
		h.logs.StopTail()
		h.zoomed = false
		if h.serviceName != "" {
			h.loading = true
			return h, tea.Batch(h.spinner.Tick, h.loadTasks(h.clusterName, h.serviceName))
		}
		h.loading = true
		return h, tea.Batch(h.spinner.Tick, h.loadServiceNames(h.clusterName))
	}

	return h, nil
}

func (h Home) View() tea.View {
	var content string

	if h.err != nil {
		errText := shared.ErrorStyle.Render(fmt.Sprintf("Error: %v", h.err))
		hint := shared.HelpStyle.Render("\n\n  Press esc to go back, q to quit")
		content = lipgloss.Place(h.width, h.height, lipgloss.Left, lipgloss.Top,
			fmt.Sprintf("\n%s%s", errText, hint))
	} else if h.loading {
		content = lipgloss.Place(h.width, h.height, lipgloss.Left, lipgloss.Center,
			fmt.Sprintf("  %s Loading...", h.spinner.View()))
	} else {
		panelH := h.height - 2
		if panelH < 3 {
			panelH = 3
		}
		innerH := panelH - 2
		bc := "  " + h.breadcrumb()
		help := shared.HelpStyle.Render(h.helpText())

		if h.zoomed {
			fw := h.width
			if h.active == viewLogsActive && h.logs.InDetailMode() {
				topH := innerH * 60 / 100
				botH := innerH - topH
				h.logs.SetDetailSizes(fw-2, topH-2, fw-2, botH-2)
				topContent := lipgloss.Place(fw-2, topH-2, lipgloss.Left, lipgloss.Top, h.logs.View())
				botContent := lipgloss.Place(fw-2, botH-2, lipgloss.Left, lipgloss.Top, h.logs.DetailView())
				topPane := shared.PaneBorder.Render(topContent)
				botPane := shared.ActiveBorder.Render(botContent)
				panes := lipgloss.JoinVertical(lipgloss.Left, topPane, botPane)
				content = lipgloss.JoinVertical(lipgloss.Left, bc, panes, help)
			} else {
				h.setActiveViewSize(fw-2, innerH)
				rightContent := lipgloss.Place(fw-2, innerH, lipgloss.Left, lipgloss.Top, h.activeDetailView())
				pane := shared.PaneBorder.Render(rightContent)
				content = lipgloss.JoinVertical(lipgloss.Left, bc, pane, help)
			}
		} else {
			lw := h.width * 2 / 5
			dw := h.width - lw

			leftContent := lipgloss.Place(lw-2, innerH, lipgloss.Left, lipgloss.Top, h.activeListView())
			rightContent := lipgloss.Place(dw-2, innerH, lipgloss.Left, lipgloss.Top, h.activeDetailView())

			leftPane := shared.ActiveBorder.Render(leftContent)
			rightPane := shared.PaneBorder.Render(rightContent)

			panes := lipgloss.JoinHorizontal(lipgloss.Top, leftPane, rightPane)
			content = lipgloss.JoinVertical(lipgloss.Left, bc, panes, help)
		}
	}

	v := tea.NewView(content)
	v.AltScreen = true
	v.WindowTitle = "ecsx"
	return v
}

// --- Helpers ---

func (h *Home) updateSizes() {
	panelH := h.height - 2
	if panelH < 3 {
		panelH = 3
	}
	innerH := panelH - 2
	h.clusters.SetSize(h.width, innerH)
	h.services.SetSize(h.width, innerH)
	h.tasks.SetSize(h.width, innerH)
	if h.active == viewLogsActive {
		h.logs.SetSize(h.width, innerH)
	}
	lw := h.width * 2 / 5
	h.ec2List.SetSize(lw-2, innerH)
	h.containerList.SetSize(lw-2, innerH)
}

func (h *Home) setActiveViewSize(w, ht int) {
	switch h.active {
	case viewLogsActive:
		h.logs.SetSize(w, ht)
	}
}

func (h Home) activeListView() string {
	switch h.active {
	case viewClustersActive:
		return h.clusters.View()
	case viewServicesActive:
		return h.services.View()
	case viewTasksActive:
		return h.tasks.View()
	case viewEC2Active:
		return h.ec2List.View()
	case viewContainerSelectActive:
		return h.containerList.View()
	case viewLogsActive:
		return h.logs.View()
	}
	return ""
}

func (h Home) activeDetailView() string {
	switch h.active {
	case viewClustersActive:
		return h.clusters.DetailView()
	case viewServicesActive:
		return h.services.DetailView()
	case viewTasksActive:
		return h.tasks.DetailView()
	case viewLogsActive:
		return h.logs.View()
	}
	return ""
}

func (h Home) breadcrumb() string {
	parts := []string{"clusters"}
	if h.clusterName != "" {
		parts = append(parts, h.clusterName)
	}
	if h.serviceName != "" {
		parts = append(parts, h.serviceName)
	}
	if h.active == viewLogsActive {
		parts = append(parts, "logs")
	}
	if h.active == viewEC2Active {
		parts = append(parts, "ec2")
	}
	return shared.BreadcrumbStyle.Render(strings.Join(parts, " › "))
}

func (h Home) helpText() string {
	switch h.active {
	case viewClustersActive:
		return h.clusters.HelpText()
	case viewServicesActive:
		return h.services.HelpText()
	case viewTasksActive:
		return h.tasks.HelpText()
	case viewLogsActive:
		return h.logs.HelpText()
	}
	parts := []string{"↑↓ navigate", "enter select", "esc back", "? help", "q quit"}
	return "  " + strings.Join(parts, " • ")
}

func (h Home) isModalActive() bool {
	switch h.active {
	case viewServicesActive:
		return h.services.IsScaling() || h.services.IsConfirming()
	case viewTasksActive:
		return h.tasks.IsConfirming()
	case viewLogsActive:
		return h.logs.IsFiltering() || h.logs.IsGrepping()
	}
	return false
}

func (h Home) isListFiltering() bool {
	switch h.active {
	case viewClustersActive:
		return h.clusters.FilterState() == list.Filtering
	case viewServicesActive:
		return h.services.FilterState() == list.Filtering
	case viewTasksActive:
		return h.tasks.FilterState() == list.Filtering
	case viewEC2Active:
		return h.ec2List.FilterState() == list.Filtering
	case viewContainerSelectActive:
		return h.containerList.FilterState() == list.Filtering
	}
	return false
}

func (h *Home) yankEnvVars(containers []ecsaws.ContainerDefinition) (Home, tea.Cmd) {
	var b strings.Builder
	for _, cd := range containers {
		for _, ev := range cd.EnvVars {
			fmt.Fprintf(&b, "export %s=%q\n", ev.Name, ev.Value)
		}
	}
	err := copyToClipboard(b.String())
	if err != nil {
		h.err = fmt.Errorf("clipboard: %w", err)
	}
	return *h, nil
}

// --- Commands ---

func (h Home) loadClusters() tea.Cmd {
	client := h.client
	return func() tea.Msg {
		clusters, err := client.ListClusters(context.Background())
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.ClustersLoaded{Clusters: clusters}
	}
}

func (h Home) loadServiceNames(cluster string) tea.Cmd {
	client := h.client
	return func() tea.Msg {
		names, err := client.ListServiceNames(context.Background(), cluster)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.ServiceNamesLoaded{Names: names}
	}
}

func (h Home) loadTasks(cluster, service string) tea.Cmd {
	client := h.client
	return func() tea.Msg {
		tasks, err := client.ListTasks(context.Background(), cluster, service)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.TasksLoaded{Tasks: tasks}
	}
}

func (h Home) loadContainerInstances(cluster string) tea.Cmd {
	client := h.client
	return func() tea.Msg {
		instances, err := client.ListContainerInstances(context.Background(), cluster)
		if err != nil {
			return messages.Err{Err: err}
		}
		return messages.EC2InstancesLoaded{Instances: instances}
	}
}

func (h Home) findLogGroups(cluster, service string) tea.Cmd {
	client := h.client
	return func() tea.Msg {
		groups, err := ecsaws.FindLogGroups(context.Background(), client, cluster, service)
		if err != nil {
			return messages.Err{Err: err}
		}
		if len(groups) == 0 {
			return messages.Err{Err: fmt.Errorf("no log groups found for service %s", service)}
		}
		if len(groups) == 1 {
			return messages.LogGroupFound{LogGroup: groups[0].LogGroup, StreamPrefix: groups[0].StreamPrefix}
		}
		return messages.LogGroupsFound{Groups: groups}
	}
}

package ui

import (
	"fmt"

	tea "charm.land/bubbletea/v2"
	"charm.land/bubbles/v2/list"

	ecsaws "github.com/ron/ecsx/internal/aws"
	"github.com/ron/ecsx/internal/ui/messages"
	clustersview "github.com/ron/ecsx/internal/ui/views/clusters"
)

func (h Home) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	// If there's an error, handle esc/q
	if h.err != nil {
		switch msg.String() {
		case "esc":
			h.err = nil
			return h, nil
		case "q", "ctrl+c":
			return h, tea.Quit
		}
		return h, nil
	}

	// Global quit (unless filtering or in a modal)
	if !h.isListFiltering() && !h.isModalActive() {
		switch msg.String() {
		case "q", "ctrl+c":
			return h, tea.Quit
		case "?":
			h.showHelp = !h.showHelp
			return h, nil
		case "+", "-":
			h.zoomed = !h.zoomed
			h.updateSizes()
			return h, nil
		case "r":
			return h.handleRefresh()
		case "a":
			h.autoRefresh = !h.autoRefresh
			return h, nil
		}
	}

	// Delegate to active view
	switch h.active {
	case viewClustersActive:
		return h.handleClustersKey(msg)
	case viewServicesActive:
		return h.handleServicesKey(msg)
	case viewTasksActive:
		return h.handleTasksKey(msg)
	case viewLogsActive:
		return h.handleLogsKey(msg)
	case viewEC2Active:
		return h.handleEC2Key(msg)
	case viewContainerSelectActive:
		return h.handleContainerSelectKey(msg)
	}
	return h, nil
}

func (h Home) handleClustersKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	cmd := h.clusters.Update(msg)

	// Check if the view emitted a navigation message by running the cmd
	// We handle cluster-specific navigation via the exported helpers
	if !h.isListFiltering() {
		switch msg.String() {
		case "enter":
			if c := h.clusters.SelectedCluster(); c != nil {
				h.clusterName = c.Name
				h.loading = true
				return h, tea.Batch(h.spinner.Tick, h.loadServiceNames(c.Name))
			}
		case "x":
			if c := h.clusters.SelectedCluster(); c != nil {
				h.clusterName = c.Name
				h.loading = true
				return h, tea.Batch(h.spinner.Tick, h.loadContainerInstances(c.Name))
			}
		}
	}

	return h, cmd
}

func (h Home) handleServicesKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	cmd := h.services.Update(msg)
	return h, cmd
}

func (h Home) handleTasksKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	cmd := h.tasks.Update(msg)
	return h, cmd
}

func (h Home) handleLogsKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	cmd := h.logs.Update(msg)
	return h, cmd
}

func (h Home) handleEC2Key(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		if h.ec2List.FilterState() != list.Filtering {
			sel := h.ec2List.SelectedItem()
			if sel != nil {
				inst := sel.(ec2Item).instance
				return h, startSSMSession(inst.EC2InstanceID, h.client.Region(), h.client.Profile())
			}
		}
	case "esc":
		if h.ec2List.FilterState() != list.Filtering {
			h.loading = true
			return h, tea.Batch(h.spinner.Tick, h.loadClusters())
		}
	}
	var cmd tea.Cmd
	h.ec2List, cmd = h.ec2List.Update(msg)
	return h, cmd
}

func (h Home) handleContainerSelectKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "enter":
		if h.containerList.FilterState() != list.Filtering {
			sel := h.containerList.SelectedItem()
			if sel != nil {
				g := sel.(containerLogItem).group
				cmd := h.logs.StartTail(g.LogGroup, g.StreamPrefix, "")
				h.active = viewLogsActive
				h.zoomed = true
				return h, cmd
			}
		}
	case "esc":
		if h.containerList.FilterState() != list.Filtering {
			if h.serviceName != "" {
				h.loading = true
				return h, tea.Batch(h.spinner.Tick, h.loadTasks(h.clusterName, h.serviceName))
			}
			h.loading = true
			return h, tea.Batch(h.spinner.Tick, h.loadServiceNames(h.clusterName))
		}
	}
	var cmd tea.Cmd
	h.containerList, cmd = h.containerList.Update(msg)
	return h, cmd
}

func (h Home) handleRefresh() (Home, tea.Cmd) {
	if h.loading {
		return h, nil
	}
	if cc, ok := h.client.(*ecsaws.CachedClient); ok {
		cc.Purge()
	}
	h.loading = true
	h.err = nil
	switch h.active {
	case viewClustersActive:
		return h, tea.Batch(h.spinner.Tick, h.loadClusters())
	case viewServicesActive:
		return h, tea.Batch(h.spinner.Tick, h.loadServiceNames(h.clusterName))
	case viewTasksActive:
		return h, tea.Batch(h.spinner.Tick, h.loadTasks(h.clusterName, h.serviceName))
	case viewEC2Active:
		return h, tea.Batch(h.spinner.Tick, h.loadContainerInstances(h.clusterName))
	case viewLogsActive:
		cmd := h.logs.StartTail(h.logs.LogGroup(), h.logs.StreamPrefix(), "")
		h.loading = false
		return h, cmd
	}
	return h, nil
}

