	next := homeAutoRefreshCmd()
	if !h.autoRefresh || h.loading || h.err != nil || h.isModalActive() || h.showHelp || h.isListFiltering() {
		return h, next
	}
	if cc, ok := h.client.(*ecsaws.CachedClient); ok {
		cc.Purge()
	}
	h.refreshing = true
	switch h.active {
	case viewClustersActive:
		return h, tea.Batch(next, h.loadClusters())
	case viewServicesActive:
		return h, tea.Batch(next, h.loadServiceNames(h.clusterName))
	case viewTasksActive:
