// Package dialogs provides modal dialog components for the ecsx TUI.
// Each dialog is a self-contained bubbletea sub-model with its own
// Update/View lifecycle. The root model manages open/close and renders
// dialogs as lipgloss layers centered on screen.
package dialogs

import (
	"fmt"
	"strings"

	"charm.land/lipgloss/v2"

	"github.com/ron/ecsx/internal/ui/shared"
)

// Overlay renders content as a centered modal overlay on top of background.
func Overlay(bg string, dialog string, bgWidth, bgHeight int) string {
	return lipgloss.Place(bgWidth, bgHeight, lipgloss.Center, lipgloss.Center,
		dialog,
		lipgloss.WithWhitespaceChars(" "),
	)
}

// DialogBox wraps content in a styled border for modal display.
func DialogBox(content string, width int) string {
	style := lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("69")).
		Padding(1, 2).
		Width(width)
	return style.Render(content)
}

