// Package search provides a bottom-bar search component for filtering lists.
// Inspired by dynamite's search bar pattern: a text input rendered at the
// bottom of the page that filters items in real-time as the user types.
package search

import (
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/bubbles/v2/textinput"
	"charm.land/lipgloss/v2"
)

var (
	barStyle = lipgloss.NewStyle().
			Foreground(lipgloss.Color("69")).
			Bold(true)
	inputStyle = lipgloss.NewStyle().
			Foreground(lipgloss.Color("252"))
)

// Bar is a bottom search bar component that filters list items.
type Bar struct {
	input  textinput.Model
	active bool
	query  string
	width  int
}

// New creates a new search bar.
func New() Bar {
	ti := textinput.New()
	ti.Placeholder = "type to filter..."
	ti.Prompt = " / "
	ti.PromptStyle = barStyle
	ti.TextStyle = inputStyle
	ti.SetWidth(40)
	return Bar{input: ti}
}

// Active returns whether the search bar is currently focused.
func (b *Bar) Active() bool {
	return b.active
}

// Query returns the current search query (even when bar is dismissed).
func (b *Bar) Query() string {
	return b.query
}

// SetWidth sets the available width for the search bar.
func (b *Bar) SetWidth(w int) {
	b.width = w
	b.input.SetWidth(w - 4)
}

// Focus activates the search bar and focuses the text input.
func (b *Bar) Focus() tea.Cmd {
	b.active = true
	b.input.SetValue(b.query)
	return b.input.Focus()
}

// Blur deactivates the search bar.
func (b *Bar) Blur() {
	b.active = false
	b.input.Blur()
}

// Clear resets the search query and deactivates the bar.
func (b *Bar) Clear() {
	b.query = ""
	b.active = false
	b.input.SetValue("")
	b.input.Blur()
}

// Update handles key messages when the bar is active.
// Returns a bool indicating if the message was consumed.
func (b *Bar) Update(msg tea.KeyPressMsg) (consumed bool, cmd tea.Cmd) {
	if !b.active {
		return false, nil
	}

	switch msg.String() {
	case "enter":
		// Accept current filter and dismiss bar
		b.query = b.input.Value()
		b.Blur()
		return true, nil
	case "esc":
		// Cancel: clear filter and dismiss
		b.Clear()
		return true, nil
	default:
		var c tea.Cmd
		b.input, c = b.input.Update(msg)
		b.query = b.input.Value()
		return true, c
	}
}

// Matches returns true if the given value matches the current query.
// Uses case-insensitive substring matching.
func (b *Bar) Matches(value string) bool {
	if b.query == "" {
		return true
	}
	return strings.Contains(
		strings.ToLower(value),
		strings.ToLower(b.query),
	)
}

// View renders the search bar. Returns empty string if not active and no query.
func (b *Bar) View() string {
	if b.active {
		return b.input.View()
	}
	if b.query != "" {
		return barStyle.Render(" / ") + inputStyle.Render(b.query) + lipgloss.NewStyle().Foreground(lipgloss.Color("241")).Render(" (/ to edit, esc to clear)")
	}
	return ""
}

